//! Phase 47 — unify the alert events from Phase 36 / 40 / 44 / 45 and push them to external webhooks.
//!
//! Listens for four kinds of event on the EventBus:
//! - `plugin.metrics.exceeded` (Phase 45: CPU / memory / thread count over threshold)
//! - `capability.sla.violated` (Phase 36: p95 latency / failure rate over threshold)
//! - `plugin.kill_switch.enabled` (Phase 44: user enables the global kill switch)
//! - `plugin.lifecycle.crashed` (Phase 40: plugin process crashed)
//!
//! Each event carries a `WebhookSources` flag deciding whether to forward it; once enabled it goes through dedup → POST.
//!
//! Persistence: `settings_kv` key = `alerting_webhook_config`, the full config as JSON.
//!
//! dedup: within a `min_interval_secs` second window the same `(source, payload-hash)` is not re-sent,
//! preventing a sustained 99% CPU from flooding the webhook. The hash uses DefaultHasher (non-cryptographic, used only for
//! short-window dedup).
//!
//! URL validation: must start with `http://` or `https://`, length ≤ 2048, no `..` / newline.
//! localhost / 127.0.0.1 are not explicitly banned (if the user wants to test against a local server, let them).

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::sync::{Arc, Mutex, OnceLock};
use std::time::{Duration, Instant};

use super::event::{OpencapxEvent, EventBus};
use super::storage::{
    AckRuleRow, AggregationRuleRow, AlertingEndpointRow, CorrelationRuleRow, EscalationRuleRow,
    FailedDeliveryRow, RouteRuleRow, SilenceRuleRow, StoreEnum,
};
use super::marketplace::hmac_sha256_hex;

const CONFIG_KEY: &str = "alerting_webhook_config";
const RETRY_CONFIG_KEY: &str = "alerting_retry_config";
const POLL_RETRY_SECS: u64 = 30;
const MAX_FETCH_PER_SCAN: usize = 50;

/// One toggle for each of the four alert sources.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct WebhookSources {
    pub metrics_exceeded: bool,
    pub sla_violated: bool,
    pub kill_switch_engaged: bool,
    pub plugin_crashed: bool,
}

impl Default for WebhookSources {
    fn default() -> Self {
        // all false — the user ticks each one after enabling the webhook
        Self {
            metrics_exceeded: false,
            sla_violated: false,
            kill_switch_engaged: false,
            plugin_crashed: false,
        }
    }
}

/// Webhook config. When `enabled = false` all fields are advisory and no request is sent.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct WebhookConfig {
    pub enabled: bool,
    pub url: String,
    pub min_interval_secs: u32,
    pub sources: WebhookSources,
    /// Custom headers (commonly used to carry the auth header for Slack / Discord).
    pub custom_headers: Vec<(String, String)>,
    /// Phase 52: `0` = Phase 47/49 legacy payload `{source, timestamp, data}` (default);
    /// `1` = canonical envelope `{schema_version, event_id, source, severity, tags, timestamp, payload}`。
    #[serde(default)]
    pub schema_version: u32,
}

/// Phase 49 — WebhookEndpoint DTO used by the frontend.
/// Almost identical in shape to `AlertingEndpointRow`, but `id` is generated by the frontend (uuid-ish) via the `add` command, and `created_at` is filled by the backend.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct WebhookEndpoint {
    /// Empty string = create (backend generates); non-empty = update.
    #[serde(default)]
    pub id: String,
    pub name: String,
    pub url: String,
    pub enabled: bool,
    pub headers: Vec<(String, String)>,
    #[serde(default)]
    pub secret: String,
    #[serde(default)]
    pub source_filter: Vec<String>,
    /// Phase 52: same as `WebhookConfig.schema_version` above. Defaults to 0 (backward compatible).
    #[serde(default)]
    pub schema_version: u32,
    /// Phase 57: per-endpoint template (`None` = use the default envelope; `Some(...)` = render this template,
    /// supporting `{{source}}` / `{{severity}}` / `{{timestamp}}` / `{{payload.x}}` + `{{#if expr}}`
    /// + `{{#each path}}`). See `render_template` for details.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub template: Option<String>,
    /// Phase 58: sample JSON entered by the user while editing the template in the settings UI, used as live preview input.
    /// `None` = use `{}` as envelope.payload when previewing. 16 KB cap, validated by the frontend before save.
    #[serde(default, rename = "templateSample", skip_serializing_if = "Option::is_none")]
    pub template_sample: Option<String>,
    /// Phase 72 — per-source severity override. Overwrites envelope_severity during fanout.
    /// `Vec<(source, severity)>` exact match (not glob). Precedence: endpoint override > user hint > manifest > default.
    #[serde(default)]
    pub severity_overrides: Vec<(String, Severity)>,
}

/// Phase 52 — Severity level (coarse-grained, used for the canonical envelope + Slack color mapping).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Severity {
    Info,
    Warn,
    Error,
    Critical,
}

impl Severity {
    pub fn as_str(self) -> &'static str {
        match self {
            Severity::Info => "info",
            Severity::Warn => "warn",
            Severity::Error => "error",
            Severity::Critical => "critical",
        }
    }
    pub fn parse(s: &str) -> Option<Severity> {
        match s.to_ascii_lowercase().as_str() {
            "info" => Some(Severity::Info),
            "warn" | "warning" => Some(Severity::Warn),
            "error" | "err" => Some(Severity::Error),
            "critical" | "crit" | "fatal" => Some(Severity::Critical),
            _ => None,
        }
    }
}

/// Phase 52 — Canonical envelope (JSON), v1 fields fixed + forward compatible.
/// Older webhook receivers can distinguish v0/v1 via the `schema_version` field.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AlertEnvelope {
    pub schema_version: u32,
    pub event_id: String,
    pub source: String,
    pub severity: Severity,
    #[serde(default)]
    pub tags: Vec<String>,
    pub timestamp: u64, // unix seconds
    pub payload: serde_json::Value,
}

/// Phase 52 — Current schema version constant.
pub const ALERT_SCHEMA_VERSION: u32 = 1;

/// Phase 50 — SilenceRule DTO used by the frontend.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SilenceRule {
    /// Empty string = create (backend generates).
    #[serde(default)]
    pub id: String,
    pub name: String,
    /// `*` matches all / `plugin.metrics.*` prefix match / `exact.kind` exact match.
    #[serde(default = "default_kind_pattern")]
    pub kind_pattern: String,
    pub starts_at: u64,
    pub ends_at: u64,
    /// 7-bit bitmask (Mon=1, Tue=2, ..., Sun=64); 0 = never fires (rejected by validation).
    #[serde(default = "default_weekdays")]
    pub weekdays: u8,
    #[serde(default)]
    pub start_hour: u8,
    #[serde(default = "default_end_hour")]
    pub end_hour: u8,
}

fn default_kind_pattern() -> String { "*".into() }
fn default_weekdays() -> u8 { 127 }
fn default_end_hour() -> u8 { 24 }

/// Phase 50 — AckRule DTO used by the frontend.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AckRule {
    pub kind_pattern: String,
    /// Suppression window length (seconds); the frontend passes minutes and the backend converts.
    pub window_secs: u64,
}

/// Phase 51 — DSL RouteRule DTO used by the frontend (`when` + `then`).
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RouteRule {
    #[serde(default)]
    pub id: String,
    pub name: String,
    #[serde(default = "default_route_priority")]
    pub priority: i32,
    #[serde(default = "default_route_enabled")]
    pub enabled: bool,
    #[serde(default = "default_kind_pattern")]
    pub kind_pattern: String,
    #[serde(default)]
    pub payload_path: Option<String>,
    #[serde(default)]
    pub payload_match: Option<String>,
    /// Phase 51 — legacy field, references a WebhookEndpoint id.
    /// Since Phase 66 prefer `recipients` (supports webhook / log:stderr / log:file / email:smtp).
    /// Kept for backward compatibility: when recipients is empty, fall back to `["webhook:{id}" for id in target_endpoint_ids]`.
    #[serde(default)]
    pub target_endpoint_ids: Vec<String>,
    /// Phase 66 — multi-channel recipient refs (each spec resolved by `notification::resolve_recipient`).
    #[serde(default)]
    pub recipients: Vec<String>,
    #[serde(default)]
    pub tags: Vec<String>,
    /// Phase 68 — temporal correlation condition: only when an event matching `pattern` occurred within the past `window_secs`
    /// does this route fan out. `None` means unconditional fanout.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub seen_in_last: Option<SeenInLastSpec>,
}

/// Phase 68 — Route temporal correlation condition.
/// `pattern` uses Phase 51's `kind_matches` glob (`*` / `**.*`).
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SeenInLastSpec {
    pub pattern: String,
    pub window_secs: u64,
}

fn default_route_priority() -> i32 {
    100
}
fn default_route_enabled() -> bool {
    true
}

/// Phase 51 — YAML import/export top-level format:
/// ```yaml
/// version: 1
/// rules:
///   - name: critical → ops
///     priority: 10
///     when:
///       kind_pattern: "plugin.metrics.*"
///       payload_path: "cpu_percent"
///       payload_match: ">=90"
///     then:
///       target_endpoint_ids: ["ep-oncall"]
///       tags: ["p1", "page"]
/// ```
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RouteRuleYamlDoc {
    #[serde(default = "default_yaml_version")]
    pub version: u32,
    pub rules: Vec<RouteRule>,
}
fn default_yaml_version() -> u32 {
    1
}

impl Default for WebhookConfig {
    fn default() -> Self {
        Self {
            enabled: false,
            url: String::new(),
            min_interval_secs: 5,
            sources: WebhookSources::default(),
            custom_headers: Vec::new(),
            schema_version: 0,
        }
    }
}

pub fn validate_url(url: &str) -> Result<(), String> {
    if url.is_empty() {
        return Err("url is required when webhook is enabled".into());
    }
    if url.len() > 2048 {
        return Err("url too long (max 2048 chars)".into());
    }
    let lower = url.to_ascii_lowercase();
    if !lower.starts_with("https://") && !lower.starts_with("http://") {
        return Err("url must start with http:// or https://".into());
    }
    // guard against header injection / path traversal characters
    if url.contains('\n') || url.contains('\r') || url.contains('\0') {
        return Err("url contains invalid control characters".into());
    }
    Ok(())
}

pub fn validate(cfg: &WebhookConfig) -> Result<(), String> {
    if !cfg.enabled {
        return Ok(()); // when disabled the url may be empty, and the other fields are not enforced either
    }
    validate_url(&cfg.url)?;
    if cfg.min_interval_secs > 3600 {
        return Err(format!(
            "min_interval_secs out of range (0..=3600): {}",
            cfg.min_interval_secs
        ));
    }
    for (k, _) in &cfg.custom_headers {
        if k.is_empty() || k.contains('\n') || k.contains('\r') {
            return Err("custom header name invalid".into());
        }
    }
    Ok(())
}

/// Phase 49 — Validate endpoint arguments.
pub fn validate_endpoint(ep: &WebhookEndpoint) -> Result<(), String> {
    let name = ep.name.trim();
    if name.is_empty() {
        return Err("endpoint name is required".into());
    }
    if name.len() > 128 {
        return Err("endpoint name too long (max 128 chars)".into());
    }
    validate_url(&ep.url)?;
    for (k, _) in &ep.headers {
        if k.is_empty() || k.contains('\n') || k.contains('\r') {
            return Err("endpoint header name invalid".into());
        }
    }
    if ep.secret.len() > 1024 {
        return Err("endpoint secret too long (max 1024 chars)".into());
    }
    // source_filter is limited to the 4 known kinds (prevents the frontend from passing arbitrary strings).
    for s in &ep.source_filter {
        if !matches!(
            s.as_str(),
            "plugin.metrics.exceeded"
                | "capability.sla.violated"
                | "plugin.kill_switch.enabled"
                | "plugin.lifecycle.crashed"
        ) {
            return Err(format!("unknown source filter: {}", s));
        }
    }
    // Phase 72 — severity_overrides validation (empty / length / valid severity string)
    for (i, (src, sev)) in ep.severity_overrides.iter().enumerate() {
        if src.trim().is_empty() {
            return Err(format!("severity_overrides[{}]: source is required", i));
        }
        if src.len() > 256 {
            return Err(format!(
                "severity_overrides[{}]: source too long (max 256 chars)",
                i
            ));
        }
        if Severity::parse(sev.as_str()).is_none() {
            return Err(format!(
                "severity_overrides[{}]: invalid severity '{}' (expected info|warn|error|critical)",
                i, sev.as_str()
            ));
        }
    }
    Ok(())
}

// Phase 72 — Severity per-source override helpers
// Phase 73 — pattern upgraded to glob (reuses Phase 51 `kind_matches`)

/// Given a source + endpoint override list, find the **first** matching severity by glob semantics, or None.
/// glob rules (same as Phase 51 `kind_matches`):
///   - `*` or `""` → matches all sources
///   - `prefix.*` → matches a prefix start + at least one character after `.`
///   - `exact` → exact match
/// Order: iterate in Vec order, **first-match wins** (consistent with the Phase 51 route DSL).
pub fn endpoint_severity_override_for(
    source: &str,
    overrides: &[(String, Severity)],
) -> Option<Severity> {
    overrides
        .iter()
        .find(|(pattern, _)| kind_matches(pattern, source))
        .map(|(_, sev)| *sev)
}

/// During fanout: if there is an endpoint override, overwrite envelope_severity; otherwise keep the propagation result
pub fn apply_endpoint_severity_override(
    envelope_severity: &mut Severity,
    source: &str,
    overrides: &[(String, Severity)],
) {
    if let Some(sev) = endpoint_severity_override_for(source, overrides) {
        *envelope_severity = sev;
    }
}

pub fn load_config() -> WebhookConfig {
    let Some(store) = super::shared_store() else {
        return WebhookConfig::default();
    };
    store
        .lock()
        .ok()
        .and_then(|s| s.get_setting(CONFIG_KEY))
        .and_then(|json| serde_json::from_str::<WebhookConfig>(&json).ok())
        .unwrap_or_default()
}

pub fn save_config(cfg: &WebhookConfig) -> Result<(), String> {
    validate(cfg)?;
    let store = super::shared_store().ok_or_else(|| "store not initialized".to_string())?;
    let mut s = store
        .lock()
        .map_err(|_| "store poisoned".to_string())?;
    let json = serde_json::to_string(cfg).map_err(|e| format!("serialize: {}", e))?;
    s.set_setting(CONFIG_KEY, &json);
    Ok(())
}

#[derive(Default)]
struct DispatcherInner {
    /// key = dedup_key(source, payload) → last sent time
    last_sent: HashMap<String, Instant>,
}

static SHARED: OnceLock<Arc<Mutex<DispatcherInner>>> = OnceLock::new();

fn shared() -> Arc<Mutex<DispatcherInner>> {
    SHARED.get_or_init(|| Arc::new(Mutex::new(DispatcherInner::default()))).clone()
}

/// Compute a stable dedup key for the payload (same source + payload sent only once within a short window).
fn dedup_key(source: &str, payload: &serde_json::Value) -> String {
    let mut h = std::collections::hash_map::DefaultHasher::new();
    source.hash(&mut h);
    // to_string() is deterministic JSON → same payload, same hash
    payload.to_string().hash(&mut h);
    format!("{}:{:016x}", source, h.finish())
}

fn source_enabled(source: &str, sources: &WebhookSources) -> bool {
    match source {
        "plugin.metrics.exceeded" => sources.metrics_exceeded,
        "capability.sla.violated" => sources.sla_violated,
        "plugin.kill_switch.enabled" => sources.kill_switch_engaged,
        "plugin.lifecycle.crashed" => sources.plugin_crashed,
        _ => false,
    }
}

/// Phase 49 — whether an endpoint accepts a source. Empty filter = accept all.
fn endpoint_accepts_source(ep: &AlertingEndpointRow, source: &str) -> bool {
    ep.source_filter.is_empty() || ep.source_filter.iter().any(|s| s == source)
}

/// Phase 49 — Fetch all enabled endpoints (an empty store returns empty, fanout skipped).
fn load_enabled_endpoints() -> Vec<AlertingEndpointRow> {
    let Some(store) = super::shared_store() else { return Vec::new() };
    let Ok(s) = store.lock() else { return Vec::new() };
    if let StoreEnum::Db(db) = &*s {
        db.list_enabled_alerting_endpoints()
    } else {
        Vec::new()
    }
}

/// Phase 49 — Compute the HMAC-SHA256 signature used as the `X-OpenCapX-Signature` header value.
/// Format `sha256=<hex>` (aligned with GitHub webhook style). An empty secret returns an empty string → the caller skips adding the header.
pub fn compute_signature(secret: &str, body: &str) -> String {
    if secret.is_empty() {
        return String::new();
    }
    let hex = hmac_sha256_hex(secret.as_bytes(), body.as_bytes());
    format!("sha256={}", hex)
}

/// dispatcher entry point.
/// - Phase 47 v1: when no endpoint is registered, use the global `WebhookConfig.url` single-endpoint path.
/// - Phase 49 v2: when endpoints exist, fan out to every enabled endpoint whose source_filter matches.
pub fn dispatch(source: &str, payload: serde_json::Value) {
    let cfg = load_config();
    // Phase 50: silence + ack short-circuit earliest, before dedup / endpoint routing
    let now_secs = super::agent::now_secs();
    if is_silenced(source, now_secs) {
        return;
    }
    if is_acked(source, now_secs) {
        return;
    }
    let endpoints = load_enabled_endpoints();
    if endpoints.is_empty() {
        // v1 compatibility path
        if !cfg.enabled {
            return;
        }
        if !source_enabled(source, &cfg.sources) {
            return;
        }
        if cfg.url.is_empty() {
            return;
        }
    }
    let key = dedup_key(source, &payload);
    let now = Instant::now();
    {
        let arc = shared();
        let mut s = match arc.lock() {
            Ok(s) => s,
            Err(_) => return,
        };
        if let Some(prev) = s.last_sent.get(&key) {
            if now.duration_since(*prev).as_secs() < cfg.min_interval_secs as u64 {
                return;
            }
        }
        s.last_sent.insert(key, now);
    }

    // Phase 55: correlation suppression — evaluated before aggregation. Suppress is the outermost short-circuit.
    if matches!(
        evaluate_correlations(source, now_secs),
        CorrelationDecision::Suppress { .. }
    ) {
        return;
    }

    // Phase 54: frequency threshold aggregation — evaluated after dedup, before building the envelope.
    //   - Suppress → the whole event is dropped (return)
    //   - Downgrade / Merge → modify severity / payload; the subsequent envelope picks it up automatically
    let mut envelope_severity = severity_resolved(source);
    let agg_decision = evaluate_aggregations(source, &payload, now_secs);
    let mut effective_payload = payload.clone();
    if !apply_aggregation_decision(&agg_decision, &mut effective_payload, &mut envelope_severity) {
        return;
    }

    if endpoints.is_empty() {
        // single-endpoint compatibility path (Phase 47 behavior)
        let url = cfg.url.clone();
        let headers = cfg.custom_headers.clone();
        let schema_version = cfg.schema_version;
        let source_owned = source.to_string();
        // Phase 54: aggregation may have changed payload + severity; capture the override version here
        let effective_payload_for_thread = effective_payload.clone();
        let envelope_severity_for_thread = envelope_severity;
        // Phase 56: escalation chain — record the source + ts of a successful dispatch for the escalation poller
        record_dispatch(source, now_secs);
        std::thread::spawn(move || {
            // Phase 52: wrap the canonical envelope when schema_version=1
            // Phase 54: frequency threshold overrode severity and payload
            let (body_str, result) = if schema_version >= 1 {
                let env = make_envelope_with_severity(
                    &source_owned,
                    effective_payload_for_thread,
                    vec![],
                    envelope_severity_for_thread,
                );
                let bs = envelope_to_json_string(&env).unwrap_or_else(|_| "null".into());
                let r = send_http_with_body(&url, &headers, &bs, "application/json");
                (bs, r)
            } else {
                let result = send_http(&url, &headers, &effective_payload_for_thread, &source_owned);
                let bs = serde_json::to_string(&effective_payload_for_thread).unwrap_or_else(|_| "null".into());
                (bs, result)
            };
            if let Err(err_msg) = result {
                let retry_cfg = load_retry_config();
                let now = super::agent::now_secs();
                let next_retry = now.saturating_add(retry_cfg.initial_backoff_secs as u64);
                enqueue_failed_delivery(
                    &source_owned,
                    &url,
                    &body_str,
                    now,
                    retry_cfg.max_attempts,
                    next_retry,
                    &err_msg,
                    None,
                );
                eprintln!("[alerting] {} queued for retry: {}", source_owned, err_msg);
            }
        });
        return;
    }

    // Phase 51: DSL routing has the highest priority — on a hit, send only to that route's target endpoint and skip fanout.
    // Phase 54: route matching uses the post-aggregation effective_payload (after payload merge).
    let matched_route = match_route(source, &effective_payload);
    let route_targets = matched_route.as_ref().map(|r| r.target_endpoint_ids.clone());
    // Phase 49 fanout path
    let matched: Vec<AlertingEndpointRow> = match route_targets {
        Some(target_ids) => endpoints
            .into_iter()
            .filter(|ep| target_ids.iter().any(|t| t == &ep.id))
            .collect(),
        None => endpoints
            .into_iter()
            .filter(|ep| endpoint_accepts_source(ep, source))
            .collect(),
    };
    if matched.is_empty() {
        return;
    }
    // Phase 56: escalation chain — record one fanout dispatch
    record_dispatch(source, now_secs);
    // Phase 68: record the seen event into the ring (used by seen_in_last + timeline).
    let mut fired_names: Vec<String> = Vec::new();
    if let Some(r) = &matched_route {
        fired_names.push(r.name.clone());
    }
    let payload_summary = serde_json::to_string(&effective_payload)
        .unwrap_or_default()
        .chars()
        .take(64)
        .collect::<String>();
    record_seen_event(source, &payload_summary, now_secs, fired_names, Vec::new());
    for ep in matched {
        // Phase 72 — per-endpoint severity override takes precedence over propagation.
        // On the main thread, before spawning, parse the overrides JSON + overwrite the envelope_severity copy.
        let mut envelope_severity_clone = envelope_severity;
        if let Some(s) = ep.severity_overrides.as_deref() {
            if let Ok(pairs) = serde_json::from_str::<Vec<(String, String)>>(s) {
                let overrides: Vec<(String, Severity)> = pairs
                    .into_iter()
                    .filter_map(|(src, sev)| Severity::parse(&sev).map(|p| (src, p)))
                    .collect();
                apply_endpoint_severity_override(&mut envelope_severity_clone, source, &overrides);
            }
        }
        let payload_clone = effective_payload.clone();
        let source_owned = source.to_string();
        std::thread::spawn(move || {
            // Phase 57: per-endpoint template takes precedence; otherwise follow schema_version for envelope / legacy.
            let (body_str, content_type) = if let Some(tpl) = ep.template.as_deref() {
                let env = make_envelope_with_severity(
                    &source_owned,
                    payload_clone,
                    vec![],
                    envelope_severity_clone,
                );
                match render_template(tpl, &env) {
                    Ok((s, ct)) => (s, ct.as_content_type().to_string()),
                    Err(e) => {
                        eprintln!("[alerting] template render error on {}: {}", ep.name, e);
                        (envelope_to_json_string(&env).unwrap_or_else(|_| "null".into()),
                         "application/json".to_string())
                    }
                }
            } else if ep.schema_version >= 1 {
                let env = make_envelope_with_severity(
                    &source_owned,
                    payload_clone,
                    vec![],
                    envelope_severity_clone,
                );
                (envelope_to_json_string(&env).unwrap_or_else(|_| "null".into()),
                 "application/json".to_string())
            } else {
                let body = serde_json::json!({
                    "source": source_owned,
                    "timestamp": super::agent::now_secs(),
                    "data": payload_clone,
                });
                (serde_json::to_string(&body).unwrap_or_else(|_| "null".into()),
                 "application/json".to_string())
            };
            let headers = build_request_headers(&ep, &body_str);
            let result = send_http_with_body(&ep.url, &headers, &body_str, &content_type);
            if let Err(err_msg) = result {
                let retry_cfg = load_retry_config();
                let now = super::agent::now_secs();
                let next_retry = now.saturating_add(retry_cfg.initial_backoff_secs as u64);
                enqueue_failed_delivery(
                    &source_owned,
                    &ep.url,
                    &body_str,
                    now,
                    retry_cfg.max_attempts,
                    next_retry,
                    &err_msg,
                    Some(&ep.id),
                );
                eprintln!(
                    "[alerting] {} → endpoint {} queued for retry: {}",
                    source_owned, ep.name, err_msg
                );
            }
        });
    }
}

/// Phase 49 — Build the header list for a single request (custom headers + optional signature).
fn build_request_headers(ep: &AlertingEndpointRow, body_str: &str) -> Vec<(String, String)> {
    let mut h = ep.headers.clone();
    let sig = compute_signature(&ep.secret, body_str);
    if !sig.is_empty() {
        h.push(("X-OpenCapX-Signature".to_string(), sig));
    }
    h
}

/// POST once, returning the status code or Err(reason). `Ok(2xx)` is treated as success.
fn send_http(
    url: &str,
    headers: &[(String, String)],
    payload: &serde_json::Value,
    source: &str,
) -> Result<u16, String> {
    let body = serde_json::json!({
        "source": source,
        "timestamp": super::agent::now_secs(),
        "data": payload,
    });
    let body_str = serde_json::to_string(&body).map_err(|e| format!("serialize: {}", e))?;
    send_http_with_body(url, headers, &body_str, "application/json")
}

/// Phase 49 — Pass the body string directly (signature computation needs exact bytes, avoiding `.json()` re-serialization differences).
/// Phase 57: `content_type` is passed explicitly (default `application/json`; template rendering may switch to text/plain).
pub(crate) fn send_http_with_body(
    url: &str,
    headers: &[(String, String)],
    body_str: &str,
    content_type: &str,
) -> Result<u16, String> {
    let client = reqwest::blocking::Client::builder()
        .timeout(Duration::from_secs(5))
        .connect_timeout(Duration::from_secs(3))
        .build()
        .map_err(|e| format!("client build: {}", e))?;
    let mut req = client.post(url).header("Content-Type", content_type);
    for (k, v) in headers {
        if !k.is_empty() {
            req = req.header(k, v);
        }
    }
    req = req.body(body_str.to_string());
    let resp = req.send().map_err(|e| format!("send failed: {}", e))?;
    let status = resp.status().as_u16();
    if resp.status().is_success() {
        Ok(status)
    } else {
        Err(format!("HTTP {}", status))
    }
}

/// Manually trigger one test_send (dedup disabled), returning the HTTP status code.
/// Used by the settings UI "Test" button — lets the user immediately see whether the webhook works.
pub fn test_send() -> Result<u16, String> {
    let cfg = load_config();
    if !cfg.enabled {
        return Err("webhook not enabled".into());
    }
    validate_url(&cfg.url)?;
    let body = serde_json::json!({
        "source": "webhook.test",
        "timestamp": super::agent::now_secs(),
        "data": { "message": "Test alert from OpenCapX" },
    });
    let body_str = serde_json::to_string(&body).map_err(|e| format!("serialize: {}", e))?;
    let client = reqwest::blocking::Client::builder()
        .timeout(Duration::from_secs(5))
        .connect_timeout(Duration::from_secs(3))
        .build()
        .map_err(|e| format!("client build: {}", e))?;
    let mut req = client.post(&cfg.url).header("Content-Type", "application/json");
    for (k, v) in &cfg.custom_headers {
        if !k.is_empty() {
            req = req.header(k, v);
        }
    }
    req = req.body(body_str);
    let resp = req.send().map_err(|e| format!("send: {}", e))?;
    let status = resp.status().as_u16();
    if resp.status().is_success() {
        Ok(status)
    } else {
        Err(format!("HTTP {}", status))
    }
}

/// Start the dispatcher background thread: subscribe to the EventBus and bridge the 4 alert kinds to the webhook.
/// Idempotent: only the first call spawns the thread.
pub fn spawn_dispatcher() {
    static ONCE: OnceLock<()> = OnceLock::new();
    if ONCE.set(()).is_err() {
        return;
    }
    let bus = EventBus::shared();
    std::thread::spawn(move || {
        for e in bus.subscribe() {
            let kind = e.kind.as_str();
            match kind {
                "plugin.metrics.exceeded"
                | "capability.sla.violated"
                | "plugin.kill_switch.enabled"
                | "plugin.lifecycle.crashed" => {
                    dispatch(kind, e.payload);
                }
                _ => {}
            }
        }
    });
}

/// Test helper: clear the dedup cache (forces the next dispatch to re-send).
#[cfg(test)]
pub fn _reset_for_tests() {
    let arc = shared();
    let result = arc.lock();
    if let Ok(mut s) = result {
        s.last_sent.clear();
    }
}

// ─── Phase 49: multi-endpoint fanout + HMAC signing ──────────────────────────

/// Generate an endpoint id (based on nanos + an atomic counter).
fn gen_endpoint_id() -> String {
    use std::sync::atomic::{AtomicU64, Ordering};
    static COUNTER: AtomicU64 = AtomicU64::new(0);
    let n = COUNTER.fetch_add(1, Ordering::Relaxed);
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    format!("ep-{}-{}", nanos, n)
}

/// List all endpoints (including disabled). Sorted by created_at ascending.
pub fn list_endpoints() -> Vec<AlertingEndpointRow> {
    let Some(store) = super::shared_store() else { return Vec::new() };
    let Ok(s) = store.lock() else { return Vec::new() };
    if let StoreEnum::Db(db) = &*s {
        db.list_alerting_endpoints()
    } else {
        Vec::new()
    }
}

/// Create or update an endpoint. Empty `id` = create; non-empty = update the row with the same id.
/// Validation failure → Err; name unique constraint → Err.
pub fn save_endpoint(ep: WebhookEndpoint) -> Result<AlertingEndpointRow, String> {
    validate_endpoint(&ep)?;
    let Some(store) = super::shared_store() else { return Err("store not initialized".into()) };
    let Ok(mut s) = store.lock() else { return Err("store poisoned".into()) };
    let StoreEnum::Db(db) = &mut *s else { return Err("sqlite store required".into()) };

    // same name but different id → reject (UNIQUE would reject too, but this gives a friendly error).
    for existing in db.list_alerting_endpoints() {
        if existing.name == ep.name && existing.id != ep.id {
            return Err(format!("endpoint name already in use: {}", ep.name));
        }
    }

    let id = if ep.id.is_empty() {
        gen_endpoint_id()
    } else {
        ep.id.clone()
    };
    let now_secs = super::agent::now_secs();
    let row = AlertingEndpointRow {
        id: id.clone(),
        name: ep.name,
        url: ep.url,
        enabled: ep.enabled,
        headers: ep.headers,
        secret: ep.secret,
        source_filter: ep.source_filter,
        schema_version: ep.schema_version,
        template: ep.template,
        template_sample: ep.template_sample,
        // Phase 72 — serialize severity_overrides as a JSON Vec<(String, String)>.
        // empty list → store NULL (lets endpoint_row_to_dto return an empty Vec).
        severity_overrides: if ep.severity_overrides.is_empty() {
            None
        } else {
            let pairs: Vec<(String, String)> = ep
                .severity_overrides
                .iter()
                .map(|(s, sev)| (s.clone(), sev.as_str().to_string()))
                .collect();
            serde_json::to_string(&pairs).ok()
        },
        // use now for create; keep the existing row's created_at (avoids a time jump in the UI).
        created_at: db
            .get_alerting_endpoint(&id)
            .map(|e| e.created_at)
            .unwrap_or(now_secs),
    };
    db.upsert_alerting_endpoint(&row);
    Ok(row)
}

/// Delete an endpoint and cascade-clear its dead letters. Returns (deleted, deliveries_cleared).
pub fn delete_endpoint(id: &str) -> Result<(bool, usize), String> {
    let Some(store) = super::shared_store() else { return Err("store not initialized".into()) };
    let Ok(mut s) = store.lock() else { return Err("store poisoned".into()) };
    let StoreEnum::Db(db) = &mut *s else { return Err("sqlite store required".into()) };
    Ok(db.delete_alerting_endpoint(id))
}

/// Fetch the endpoint config → immediately POST once with source="webhook.test" (bypassing dedup).
/// Failure → Err; success → Ok(status_code). Used by the settings UI per-endpoint Test button.
pub fn test_endpoint(id: &str) -> Result<u16, String> {
    let Some(store) = super::shared_store() else { return Err("store not initialized".into()) };
    let Ok(s) = store.lock() else { return Err("store poisoned".into()) };
    let StoreEnum::Db(db) = &*s else { return Err("sqlite store required".into()) };
    let ep = db
        .get_alerting_endpoint(id)
        .ok_or_else(|| format!("endpoint not found: {}", id))?;
    drop(s);
    validate_url(&ep.url)?;
    let body = serde_json::json!({
        "source": "webhook.test",
        "timestamp": super::agent::now_secs(),
        "data": { "endpoint": ep.name, "message": "Test alert from OpenCapX" },
    });
    let body_str = serde_json::to_string(&body).map_err(|e| format!("serialize: {}", e))?;
    let headers = build_request_headers(&ep, &body_str);
    send_http_with_body(&ep.url, &headers, &body_str, "application/json")
}

// ─── Phase 52: canonical envelope + schema_version ──────────────────────────────

/// Return the default severity for a source kind; unknown sources use info.
pub fn severity_for_source(source: &str) -> Severity {
    match source {
        "plugin.metrics.exceeded" => Severity::Warn,
        "capability.sla.violated" => Severity::Error,
        "plugin.kill_switch.enabled" => Severity::Critical,
        "plugin.lifecycle.crashed" => Severity::Critical,
        "webhook.test" => Severity::Info,
        _ => Severity::Info,
    }
}

/// Generate a UUID v4 event_id. Uses the uuid crate v4 feature (already in deps, used directly).
pub fn gen_event_id() -> String {
    uuid::Uuid::new_v4().to_string()
}

/// Build the canonical envelope from `(source, payload)` (schema_version=1).
/// `tags` defaults to empty; Phase 51 routes may put extra tags there, but dispatch() does not read them yet.
/// severity follows the Phase 53 chain (stored hint → hardcoded default → Info), ensuring the plugin manifest takes effect.
pub fn make_envelope(
    source: &str,
    payload: serde_json::Value,
    tags: Vec<String>,
) -> AlertEnvelope {
    AlertEnvelope {
        schema_version: ALERT_SCHEMA_VERSION,
        event_id: gen_event_id(),
        source: source.to_string(),
        severity: severity_resolved(source),
        tags,
        timestamp: super::agent::now_secs(),
        payload,
    }
}

/// Phase 54 — severity override version of make_envelope, used by frequency threshold aggregation (downgrade).
/// Other fields are unchanged; event_id is still regenerated each time (each delivery is a new event).
pub fn make_envelope_with_severity(
    source: &str,
    payload: serde_json::Value,
    tags: Vec<String>,
    severity: Severity,
) -> AlertEnvelope {
    AlertEnvelope {
        schema_version: ALERT_SCHEMA_VERSION,
        event_id: gen_event_id(),
        source: source.to_string(),
        severity,
        tags,
        timestamp: super::agent::now_secs(),
        payload,
    }
}

/// Serialize the envelope to a JSON string; the signature is computed over the whole string's bytes (avoiding re-serialization drift).
pub fn envelope_to_json_string(env: &AlertEnvelope) -> Result<String, String> {
    serde_json::to_string(env).map_err(|e| format!("envelope serialize: {}", e))
}

// ─── Phase 57: per-endpoint template engine ──────────────────────────────────

/// Phase 57 — Template render output type: determines the Content-Type on POST.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TemplateContentType {
    Json,
    Text,
}

impl TemplateContentType {
    pub fn as_content_type(self) -> &'static str {
        match self {
            TemplateContentType::Json => "application/json",
            TemplateContentType::Text => "text/plain; charset=utf-8",
        }
    }
}

/// Phase 57 — Given an endpoint's template + envelope, produce (rendered_body, content_type).
/// Supported syntax:
///   - `{{path}}` — top-level fields (source / severity / timestamp / event_id / schema_version / tags)
///   - `{{payload.x.y.z}}` — dot-path JSON field access (numbers / bool / null go through JSON serialization)
///   - `{{#if EXPR}}BODY{{/if}}` — conditional block
///       EXPR forms:
///         `severity == "critical"` / `payload.code == 500` — equality comparison (supports string / numeric literals)
///         `payload.x` / `severity` — truthiness check (non-empty string / non-zero number / true / non-empty array / non-empty object)
///         `!EXPR` — negation
///   - `{{#if EXPR}}A{{else}}B{{/if}}` — if / else
///   - `{{#each path}}BODY{{/each}}` — iterate an array; inside the block `{{this}}` yields the element and `{{this.x}}` a field
///
/// Failure: an unpaired `{{#if}}` / `{{#each}}` returns Err (with the template's line:col).
pub fn render_template(
    template: &str,
    env: &AlertEnvelope,
) -> Result<(String, TemplateContentType), String> {
    let mut out = String::with_capacity(template.len());
    render_into(template, env, &mut out, 0, 0)?;
    let trimmed = out.trim_start();
    let ct = if trimmed.starts_with('{') || trimmed.starts_with('[') {
        TemplateContentType::Json
    } else {
        TemplateContentType::Text
    };
    Ok((out, ct))
}

/// Internal recursive render: `template` starts at `pos`, until the end or a matching `end_token` (`end_token = 0` means no external end condition).
/// Block end tokens: `{{/if}}` and `{{/each}}`.
fn render_into(
    template: &str,
    env: &AlertEnvelope,
    out: &mut String,
    pos: usize,
    end_token: u8,
) -> Result<usize, String> {
    let bytes = template.as_bytes();
    let mut i = pos;
    while i < bytes.len() {
        // match a block end
        if bytes[i..].starts_with(b"{{/if}}") {
            if end_token == 1 {
                return Ok(i + 7);
            }
            return Err(format!(
                "template: unexpected {{/if}} at offset {} (no matching {{#if}})",
                i
            ));
        }
        if bytes[i..].starts_with(b"{{/each}}") {
            if end_token == 2 {
                return Ok(i + 9);
            }
            return Err(format!(
                "template: unexpected {{/each}} at offset {} (no matching {{#each}})",
                i
            ));
        }
        // match {{ ... }}
        if bytes[i..].starts_with(b"{{") {
            // find }}
            let close = match template[i + 2..].find("}}") {
                Some(c) => i + 2 + c,
                None => {
                    return Err(format!(
                        "template: unclosed placeholder at offset {}",
                        i
                    ))
                }
            };
            let expr = template[i + 2..close].trim();
            if let Some(rest) = expr.strip_prefix("#if ") {
                // {{#if EXPR}}BODY{{/if}} / {{#if EXPR}}A{{else}}B{{/if}}
                let cond_expr = rest.trim();
                // find the BODY start (the first {{/if}} or {{else}} after close + 2)
                let body_start = close + 2;
                // first render one segment with sentinel token 1 ({{/if}}), capturing the rest
                let mut scratch = String::new();
                let after_if = render_into(template, env, &mut scratch, body_start, 1)?;
                // after_if points past the end of {{/if}}. Check whether the if-body contains {{else}}
                let if_body_str = &template[body_start..after_if - 7];
                if let Some(else_idx) = if_body_str.rfind("{{else}}") {
                    let else_body_start_in_main = body_start + else_idx + 8;
                    let mut else_scratch = String::new();
                    let _ = render_into(
                        template,
                        env,
                        &mut else_scratch,
                        else_body_start_in_main,
                        1,
                    )?;
                    let cond = eval_condition(cond_expr, env)?;
                    if cond {
                        out.push_str(&if_body_str[..else_idx]);
                    } else {
                        out.push_str(&else_scratch);
                    }
                } else {
                    let cond = eval_condition(cond_expr, env)?;
                    if cond {
                        out.push_str(&scratch);
                    }
                }
                i = after_if; // after_if already points past {{/if}}
                continue;
            }
            if let Some(rest) = expr.strip_prefix("#each ") {
                let path = rest.trim();
                // find the BODY start + grab the raw range directly (use a sentinel to locate {{/each}})
                let body_start = close + 2;
                let end_rel = match template[body_start..].find("{{/each}}") {
                    Some(p) => p,
                    None => return Err("template: unclosed {{#each}}".into()),
                };
                let body_raw = &template[body_start..body_start + end_rel];
                let after_each = body_start + end_rel + 9; // skip past {{/each}}
                // fetch the array
                let arr = lookup_path_array(env, path).unwrap_or_default();
                for item in arr {
                    // inside the block, resolve via `{{this}}` / `{{this.x}}`
                    render_each_body(body_raw, &item, env, out)?;
                }
                i = after_each;
                continue;
            }
            // plain placeholder {{path}}
            let val = lookup_path_string(env, expr);
            out.push_str(&val);
            i = close + 2;
            continue;
        }
        // ordinary character
        let ch = template[i..].chars().next().unwrap();
        out.push(ch);
        i += ch.len_utf8();
    }
    if end_token != 0 {
        return Err(format!(
            "template: unclosed block (expected {{/{}}})",
            match end_token {
                1 => "if",
                2 => "each",
                _ => "?",
            }
        ));
    }
    Ok(i)
}

/// Render a `{{#each}}` block body, mapping `{{this}}` / `{{this.x}}` to the current item.
fn render_each_body(
    body: &str,
    item: &serde_json::Value,
    env: &AlertEnvelope,
    out: &mut String,
) -> Result<(), String> {
    let bytes = body.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i..].starts_with(b"{{this") {
            // {{this}} or {{this.x.y}}
            let close = match body[i + 2..].find("}}") {
                Some(c) => i + 2 + c,
                None => return Err(format!("unclosed {{this... at {}", i)),
            };
            let expr = body[i + 2..close].trim(); // "this" or "this.x.y"
            let val = if expr == "this" {
                value_to_string(item)
            } else if let Some(rest) = expr.strip_prefix("this.") {
                let v = lookup_json_path(item, rest).unwrap_or(&serde_json::Value::Null);
                value_to_string(v)
            } else {
                // fallback: use envelope lookup (allows referencing env inside an each block too)
                lookup_path_string(env, expr)
            };
            out.push_str(&val);
            i = close + 2;
            continue;
        }
        if bytes[i..].starts_with(b"{{") {
            // plain placeholders such as {{source}} are allowed inside the block (they use env)
            let close = match body[i + 2..].find("}}") {
                Some(c) => i + 2 + c,
                None => return Err(format!("unclosed placeholder at {}", i)),
            };
            let expr = body[i + 2..close].trim();
            // nested #if / #each inside an each block is forbidden (simplified implementation)
            if expr.starts_with('#') {
                return Err(format!(
                    "nested block not supported in each: {}",
                    expr
                ));
            }
            let val = lookup_path_string(env, expr);
            out.push_str(&val);
            i = close + 2;
            continue;
        }
        let ch = body[i..].chars().next().unwrap();
        out.push(ch);
        i += ch.len_utf8();
    }
    Ok(())
}

/// Parse a condition expression: `a == "b"` / `a == 42` / `a` / `!a`.
fn eval_condition(expr: &str, env: &AlertEnvelope) -> Result<bool, String> {
    let expr = expr.trim();
    if let Some(rest) = expr.strip_prefix('!') {
        return Ok(!eval_condition(rest.trim(), env)?);
    }
    if let Some(idx) = expr.find("==") {
        let left = expr[..idx].trim();
        let right = expr[idx + 2..].trim();
        let lv = lookup_path_value(env, left);
        let rv = parse_literal(right);
        return Ok(values_equal(&lv, &rv));
    }
    // truthiness check
    let v = lookup_path_value(env, expr);
    Ok(is_truthy(&v))
}

fn parse_literal(s: &str) -> serde_json::Value {
    if s.starts_with('"') && s.ends_with('"') && s.len() >= 2 {
        return serde_json::Value::String(s[1..s.len() - 1].to_string());
    }
    if let Ok(n) = s.parse::<i64>() {
        return serde_json::Value::Number(n.into());
    }
    if let Ok(f) = s.parse::<f64>() {
        if let Some(n) = serde_json::Number::from_f64(f) {
            return serde_json::Value::Number(n);
        }
    }
    if s == "true" {
        return serde_json::Value::Bool(true);
    }
    if s == "false" {
        return serde_json::Value::Bool(false);
    }
    if s == "null" {
        return serde_json::Value::Null;
    }
    // fall back to treating it as a string literal
    serde_json::Value::String(s.to_string())
}

fn values_equal(a: &serde_json::Value, b: &serde_json::Value) -> bool {
    a == b
}

fn is_truthy(v: &serde_json::Value) -> bool {
    match v {
        serde_json::Value::Null => false,
        serde_json::Value::Bool(b) => *b,
        serde_json::Value::Number(n) => n.as_f64().map(|f| f != 0.0).unwrap_or(false),
        serde_json::Value::String(s) => !s.is_empty(),
        serde_json::Value::Array(a) => !a.is_empty(),
        serde_json::Value::Object(o) => !o.is_empty(),
    }
}

// ─── Phase 58: template lint + dry-run preview ───────────────────────────────

/// Phase 58 — Static lint diagnostic info, exposed to the frontend live preview UI.
/// `severity` uses literal strings (`"error"` / `"warning"`) aligned with serde + the TS DTO;
/// `code` is a stable machine-readable category (`unexpected_close` / `unclosed_block` /
/// `nested_too_deep` / `unclosed_placeholder` / `empty_tag` / `unknown_tag` /
/// `mismatched_close` / `render_failed`)。
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct TemplateDiagnostic {
    pub severity: &'static str,
    pub code: String,
    pub message: String,
    pub offset: usize,
    pub line: usize,
    pub column: usize,
}

/// Phase 58 — dry-run render result + lint diagnostics.
/// `body` is the rendered string (empty on failure); `content_type` is the auto-sniffed
/// (`"application/json"` or `"text/plain; charset=utf-8"`); `diagnostics`
/// is the merged list of lint + render failure info (sorted by offset).
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct TemplatePreviewResult {
    pub body: String,
    pub content_type: String,
    pub diagnostics: Vec<TemplateDiagnostic>,
}

/// Convert a byte offset in the template to (1-indexed line, 1-indexed column).
/// column is the user-visible column (UTF-8 chars count as 1, not bytes).
pub fn offset_to_line_col(template: &str, offset: usize) -> (usize, usize) {
    let mut line = 1usize;
    let mut col = 1usize;
    let bytes = template.as_bytes();
    let mut i = 0;
    while i < offset && i < bytes.len() {
        // UTF-8 chars follow char boundaries
        if let Some(ch) = template[i..].chars().next() {
            if ch == '\n' {
                line += 1;
                col = 1;
            } else {
                col += 1;
            }
            i += ch.len_utf8();
        } else {
            break;
        }
    }
    (line, col)
}

fn diag_at(
    template: &str,
    offset: usize,
    severity: &'static str,
    code: &str,
    message: &str,
) -> TemplateDiagnostic {
    let (line, column) = offset_to_line_col(template, offset);
    TemplateDiagnostic {
        severity,
        code: code.to_string(),
        message: message.to_string(),
        offset,
        line,
        column,
    }
}

/// Static lint: does not evaluate the template, only checks structure (nesting / pairing / syntax).
/// Nesting depth ≥ 9 → error; unmatched `{{/if}}` / `{{/each}}` → error;
/// unclosed `{{#if}}` / `{{#each}}` → error; unclosed `{{` → error;
/// empty placeholder / suspicious identifier syntax → warning.
pub fn lint_template(template: &str) -> Vec<TemplateDiagnostic> {
    let mut out = Vec::new();
    let mut stack: Vec<(&'static str, usize)> = Vec::new(); // (kind, open_offset)
    let mut max_depth: usize = 0;
    let bytes = template.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i..].starts_with(b"{{") {
            // find }}
            let close_rel = template[i + 2..].find("}}");
            let Some(close_rel) = close_rel else {
                out.push(diag_at(
                    template,
                    i,
                    "error",
                    "unclosed_placeholder",
                    "unclosed {{ placeholder (missing }})",
                ));
                break;
            };
            let close = i + 2 + close_rel;
            let expr = template[i + 2..close].trim();
            if let Some(rest) = expr.strip_prefix("#if ") {
                if stack.len() + 1 >= 9 {
                    out.push(diag_at(
                        template,
                        i,
                        "error",
                        "nested_too_deep",
                        "block nesting too deep (max 8)",
                    ));
                }
                max_depth = max_depth.max(stack.len() + 1);
                stack.push(("if", i));
            } else if let Some(_rest) = expr.strip_prefix("#each ") {
                if stack.len() + 1 >= 9 {
                    out.push(diag_at(
                        template,
                        i,
                        "error",
                        "nested_too_deep",
                        "block nesting too deep (max 8)",
                    ));
                }
                max_depth = max_depth.max(stack.len() + 1);
                stack.push(("each", i));
            } else if expr == "/if" {
                match stack.pop() {
                    Some(("if", _)) => {}
                    Some(("each", off)) => {
                        out.push(diag_at(
                            template,
                            i,
                            "error",
                            "mismatched_close",
                            &format!("{{{{/if}}}} closes {{{{}}}} at offset {}", off),
                        ));
                    }
                    None => {
                        out.push(diag_at(
                            template,
                            i,
                            "error",
                            "unexpected_close",
                            "unexpected {{/if}} with no matching {{#if}}",
                        ));
                    }
                    _ => unreachable!(),
                }
            } else if expr == "/each" {
                match stack.pop() {
                    Some(("each", _)) => {}
                    Some(("if", off)) => {
                        out.push(diag_at(
                            template,
                            i,
                            "error",
                            "mismatched_close",
                            &format!("{{{{/each}}}} closes {{{{}}}} at offset {}", off),
                        ));
                    }
                    None => {
                        out.push(diag_at(
                            template,
                            i,
                            "error",
                            "unexpected_close",
                            "unexpected {{/each}} with no matching {{#each}}",
                        ));
                    }
                    _ => unreachable!(),
                }
            } else if expr.is_empty() {
                out.push(diag_at(
                    template,
                    i,
                    "warning",
                    "empty_tag",
                    "empty placeholder",
                ));
            } else if expr.contains(' ') && !expr.contains("==") && !expr.starts_with('#') {
                out.push(diag_at(
                    template,
                    i,
                    "warning",
                    "unknown_tag",
                    &format!("unexpected placeholder syntax: {}", expr),
                ));
            }
            i = close + 2;
            continue;
        }
        // ordinary char (UTF-8 aware)
        let ch_len = template[i..].chars().next().map(|c| c.len_utf8()).unwrap_or(1);
        i += ch_len;
    }
    // stack not empty → unclosed block
    for (kind, off) in &stack {
        out.push(diag_at(
            template,
            *off,
            "error",
            "unclosed_block",
            &format!("unclosed {{{{#{}}}}} block", kind),
        ));
    }
    let _ = max_depth; // reserved for a future warning (range 5-8); an error is already enough to alert
    out
}

/// Phase 58 — Parse the `at offset N` at the tail of a `render_template` error message.
/// Used to upgrade a render failure into a diagnostic carrying line/col.
fn parse_error_offset(msg: &str) -> Option<usize> {
    let idx = msg.rfind("at offset ")?;
    let rest = &msg[idx + "at offset ".len()..];
    rest.split(|c: char| !c.is_ascii_digit())
        .next()
        .and_then(|s| s.parse::<usize>().ok())
}

/// Phase 58 — dry-run preview: use the sample JSON passed by the frontend as envelope.payload,
/// run render_template + lint_template, and synthesize a TemplatePreviewResult.
/// On render failure it does not return Err, but merges diagnostics + body="" (easier for the frontend).
pub fn preview_alerting_template(
    template: &str,
    sample: &serde_json::Value,
) -> TemplatePreviewResult {
    let envelope = AlertEnvelope {
        schema_version: ALERT_SCHEMA_VERSION,
        event_id: "preview".into(),
        source: "preview".into(),
        severity: Severity::Info,
        tags: vec![],
        timestamp: 0,
        payload: sample.clone(),
    };
    let mut diags = lint_template(template);
    match render_template(template, &envelope) {
        Ok((body, ct)) => TemplatePreviewResult {
            body,
            content_type: ct.as_content_type().to_string(),
            diagnostics: diags,
        },
        Err(e) => {
            if let Some(off) = parse_error_offset(&e) {
                let (line, col) = offset_to_line_col(template, off);
                diags.push(TemplateDiagnostic {
                    severity: "error",
                    code: "render_failed".into(),
                    message: e,
                    offset: off,
                    line,
                    column: col,
                });
            } else {
                diags.push(TemplateDiagnostic {
                    severity: "error",
                    code: "render_failed".into(),
                    message: e,
                    offset: 0,
                    line: 1,
                    column: 1,
                });
            }
            TemplatePreviewResult {
                body: String::new(),
                content_type: "text/plain".to_string(),
                diagnostics: diags,
            }
        }
    }
}

// ─── Phase 59: template preset library + import/export ──────────────────────

/// Phase 59 — One template preset (user-defined + 5 built-in constants).
/// `kind` distinguishes builtin / user: builtin uses `"builtin:<slug>"`, user uses `"user:<uuid>"`.
/// Phase 60 — adds `version: u32` (auto-bumped on each save of the same id; 1 the first time) + `changelog: String` (optional notes).
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TemplatePreset {
    #[serde(default)]
    pub id: String,
    pub name: String,
    #[serde(default)]
    pub description: String,
    pub kind: String,
    pub template: String,
    #[serde(default)]
    pub sample: String,
    #[serde(default)]
    pub builtin: bool,
    #[serde(default, rename = "createdAt")]
    pub created_at: u64,
    #[serde(default = "default_template_preset_version")]
    pub version: u32,
    #[serde(default)]
    pub changelog: String,
}

fn default_template_preset_version() -> u32 { 1 }

/// Phase 59 — YAML / JSON document schema. The `version` field is used for future schema migration.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PresetYamlDoc {
    #[serde(default = "default_preset_doc_version")]
    pub version: u32,
    pub presets: Vec<TemplatePreset>,
}

fn default_preset_doc_version() -> u32 { 1 }

/// Phase 61 — Current YAML/JSON document schema version. Bump when new fields are added to `TemplatePreset`.
pub const CURRENT_DOC_VERSION: u32 = 1;

/// Phase 61 — A single migration rule: `from_version → to_version` runs the `migrate` function.
/// `name` is used for logs / error diagnostics (`migrate v0→v1 (v0_to_v1) failed: ...`).
pub struct PresetMigration {
    pub from: u32,
    pub to: u32,
    pub name: &'static str,
    pub migrate: fn(PresetYamlDoc) -> Result<PresetYamlDoc, String>,
}

/// Phase 61 — v0 (yaml has no `version` field at all, or an explicit `version: 0`) → v1 migration.
/// Mainly: fill doc.version = 1; default each preset's version field to 1 (a field added in Phase 60+).
fn migrate_v0_to_v1(mut doc: PresetYamlDoc) -> Result<PresetYamlDoc, String> {
    doc.version = 1;
    for p in doc.presets.iter_mut() {
        if p.version == 0 {
            p.version = 1;
        }
        if p.changelog.is_empty() {
            // the v0 schema has no changelog field; serde default gives "", leaving it as-is.
        }
        if p.kind.is_empty() {
            // when a preset in a v0 document has no kind field (rare), default to the user namespace
            if p.id.is_empty() {
                p.id = gen_event_id();
            }
            p.kind = format!("user:{}", p.id);
        }
    }
    Ok(doc)
}

/// Phase 61 — Global migration table. Sorted by `from` ascending; `migrate_preset_yaml` finds the next step and runs it in turn.
/// Currently only `0 → 1`. When Phase 62+ adds fields, bump CURRENT_DOC_VERSION and append an entry.
pub const MIGRATORS: &[PresetMigration] = &[
    PresetMigration { from: 0, to: 1, name: "v0_to_v1", migrate: migrate_v0_to_v1 },
];

/// Phase 61 — Parse YAML / JSON and upgrade along the MIGRATORS chain to CURRENT_DOC_VERSION.
/// Returns (migrated_doc, applied_migration_names) — the former for upsert, the latter for the frontend import notice.
pub fn migrate_preset_yaml(yaml: &str) -> Result<(PresetYamlDoc, Vec<&'static str>), String> {
    let mut doc: PresetYamlDoc = serde_yaml::from_str(yaml)
        .map_err(|e| format!("yaml parse: {}", e))?;
    let mut applied: Vec<&'static str> = Vec::new();
    while doc.version < CURRENT_DOC_VERSION {
        let next = MIGRATORS.iter().find(|m| m.from == doc.version)
            .ok_or_else(|| format!(
                "no migrator available for doc version {} (current = {})",
                doc.version, CURRENT_DOC_VERSION
            ))?;
        let from = doc.version;
        doc = (next.migrate)(doc)?;
        // defensive: if the migrator did not update version correctly, fix it manually here
        if doc.version != next.to {
            eprintln!(
                "[alerting::migrate_preset_yaml] WARNING: migrator '{}' returned doc.version={} (expected {})",
                next.name, doc.version, next.to
            );
            doc.version = next.to;
        }
        eprintln!(
            "[alerting::migrate_preset_yaml] applied {} ({} → {})",
            next.name, from, doc.version
        );
        applied.push(next.name);
        // guard against infinite loops: even a buggy migrator must not run forever
        if applied.len() > 16 {
            return Err("migration chain too long (>16 steps); aborting to prevent infinite loop".into());
        }
    }
    if doc.version > CURRENT_DOC_VERSION {
        return Err(format!(
            "doc version {} is newer than current {}; refusing to import future schema",
            doc.version, CURRENT_DOC_VERSION
        ));
    }
    Ok((doc, applied))
}

/// Phase 59 — 5 built-in presets. Covers the most common webhook receivers.
/// Cached with `OnceLock` (avoids const-fn limits); all callers get them through the `builtin_presets()` function.
pub fn builtin_presets() -> &'static [TemplatePreset] {
    use std::sync::OnceLock;
    static CACHE: OnceLock<Vec<TemplatePreset>> = OnceLock::new();
    CACHE.get_or_init(|| {
        vec![
            TemplatePreset {
                id: "builtin-slack".into(),
                name: "Slack incoming webhook".into(),
                description: "Slack-compatible JSON: {\"text\":\"<msg>\"}. Mentions @oncall if tags.oncall set.".into(),
                kind: "builtin:slack".into(),
                template: r#"{
  "text": "[{{severity}}] {{source}}: {{payload.message}}{{#if payload.tags.oncall}} @{{payload.tags.oncall}}{{/if}}",
  "username": "OpenCapX",
  "icon_emoji": ":warning:"
}"#.into(),
                sample: r#"{"message":"p99 latency exceeded 500ms","tags":{"oncall":"alice"}}"#.into(),
                builtin: true,
                created_at: 0,
                version: 1,
                changelog: String::new(),
            },
            TemplatePreset {
                id: "builtin-discord".into(),
                name: "Discord webhook".into(),
                description: "Discord-compatible JSON: {\"content\":\"<msg>\"}.".into(),
                kind: "builtin:discord".into(),
                template: r#"{
  "content": "[{{severity}}] {{source}}: {{payload.message}}",
  "username": "OpenCapX"
}"#.into(),
                sample: r#"{"message":"CPU 95% on host web-1"}"#.into(),
                builtin: true,
                created_at: 0,
                version: 1,
                changelog: String::new(),
            },
            TemplatePreset {
                id: "builtin-msteams".into(),
                name: "Microsoft Teams webhook".into(),
                description: "Teams MessageCard with themeColor switching by severity.".into(),
                kind: "builtin:msteams".into(),
                template: r#"{
  "@type": "MessageCard",
  "@context": "https://schema.org/extensions",
  "themeColor": "{{#if payload.severity_eq_critical}}FF0000{{else}}{{#if payload.severity_eq_error}}FFA500{{else}}{{#if payload.severity_eq_warn}}FFCC00{{else}}00CC00{{/if}}{{/if}}{{/if}}",
  "title": "[{{severity}}] {{source}}",
  "text": "{{payload.message}}"
}"#.into(),
                sample: r#"{"message":"DB connection pool exhausted"}"#.into(),
                builtin: true,
                created_at: 0,
                version: 1,
                changelog: String::new(),
            },
            TemplatePreset {
                id: "builtin-generic-json".into(),
                name: "Generic JSON envelope".into(),
                description: "Pass the canonical envelope's payload through verbatim.".into(),
                kind: "builtin:generic_json".into(),
                template: "{{payload}}".into(),
                sample: r#"{"any":"json","nested":{"k":"v"}}"#.into(),
                builtin: true,
                created_at: 0,
                version: 1,
                changelog: String::new(),
            },
            TemplatePreset {
                id: "builtin-plain-text".into(),
                name: "Plain text".into(),
                description: "Single-line plain text format. Content-Type: text/plain.".into(),
                kind: "builtin:plain_text".into(),
                template: "[{{severity}}] {{source}} at {{timestamp}}: {{payload.message}}".into(),
                sample: r#"{"message":"hello world"}"#.into(),
                builtin: true,
                created_at: 0,
                version: 1,
                changelog: String::new(),
            },
        ]
    })
}

/// Phase 59 — builtin + user presets. If storage is uninitialized, only builtins are returned.
pub fn list_template_presets() -> Vec<TemplatePreset> {
    let mut out: Vec<TemplatePreset> = builtin_presets().to_vec();
    let Some(store) = super::shared_store() else { return out };
    let Ok(s) = store.lock() else { return out };
    let StoreEnum::Db(db) = &*s else { return out };
    if let Ok(user_rows) = db.list_user_template_presets() {
        for r in user_rows {
            out.push(TemplatePreset {
                id: r.id,
                name: r.name,
                description: r.description.unwrap_or_default(),
                kind: r.kind,
                template: r.template,
                sample: r.sample.unwrap_or_default(),
                builtin: r.builtin,
                created_at: r.created_at,
                version: r.version,
                changelog: r.changelog.unwrap_or_default(),
            });
        }
    }
    out
}

/// Phase 59 — Fetch a single preset by kind (returns both builtin and user).
pub fn get_template_preset(kind: &str) -> Option<TemplatePreset> {
    if let Some(b) = builtin_presets().iter().find(|p| p.kind == kind).cloned() {
        return Some(b);
    }
    let Some(store) = super::shared_store() else { return None };
    let Ok(s) = store.lock() else { return None };
    let StoreEnum::Db(db) = &*s else { return None };
    db.list_user_template_presets().ok()?
        .into_iter()
        .find(|r| r.kind == kind)
        .map(|r| TemplatePreset {
            id: r.id,
            name: r.name,
            description: r.description.unwrap_or_default(),
            kind: r.kind,
            template: r.template,
            sample: r.sample.unwrap_or_default(),
            builtin: r.builtin,
            created_at: r.created_at,
            version: r.version,
            changelog: r.changelog.unwrap_or_default(),
        })
}

/// Phase 59 — Save a custom preset. Validates name / template / sample size; rejects builtin=true.
/// Phase 60 — Repeated saves of the same id auto-bump version (using `max(old.version + 1, requested_version)`).
pub fn save_user_template_preset(p: &TemplatePreset) -> Result<TemplatePreset, String> {
    if p.name.trim().is_empty() {
        return Err("name required".into());
    }
    if p.name.len() > 64 {
        return Err("name too long (max 64)".into());
    }
    if p.template.len() > 16 * 1024 {
        return Err("template too large (max 16KB)".into());
    }
    if p.sample.len() > 16 * 1024 {
        return Err("sample too large (max 16KB)".into());
    }
    if p.changelog.len() > 512 {
        return Err("changelog too long (max 512 chars)".into());
    }
    if p.builtin {
        return Err("cannot save builtin preset as user".into());
    }
    let mut out = p.clone();
    if out.id.is_empty() {
        out.id = gen_event_id();
    }
    out.kind = if out.kind.is_empty() || out.kind.starts_with("builtin:") {
        format!("user:{}", out.id)
    } else {
        out.kind.clone()
    };
    let now = super::agent::now_secs();
    out.created_at = if out.created_at == 0 { now } else { out.created_at };

    // Phase 60: the same id already exists → read the old version + created_at, auto-bump version (and keep created_at).
    let store = super::shared_store().ok_or_else(|| "store unavailable".to_string())?;
    let s = store.lock().map_err(|_| "store poisoned".to_string())?;
    let StoreEnum::Db(db) = &*s else { return Err("sqlite store required".into()); };
    let existing = db.list_user_template_presets().ok()
        .and_then(|rows| rows.into_iter().find(|r| r.id == out.id));
    if let Some(old) = existing {
        out.version = old.version.saturating_add(1).max(out.version.max(1));
        if out.created_at == now || out.created_at == 0 {
            out.created_at = old.created_at;
        }
    } else {
        out.version = out.version.max(1);
        out.created_at = if out.created_at == 0 { now } else { out.created_at };
    }
    drop(s); // release the lock before writing (mutable borrow below)
    let mut s2 = store.lock().map_err(|_| "store poisoned".to_string())?;
    let StoreEnum::Db(db) = &mut *s2 else { return Err("sqlite store required".into()); };
    let row = crate::core::storage::TemplatePresetRow {
        id: out.id.clone(),
        name: out.name.clone(),
        description: if out.description.is_empty() { None } else { Some(out.description.clone()) },
        kind: out.kind.clone(),
        template: out.template.clone(),
        sample: if out.sample.is_empty() { None } else { Some(out.sample.clone()) },
        builtin: false,
        version: out.version,
        changelog: if out.changelog.is_empty() { None } else { Some(out.changelog.clone()) },
        created_at: out.created_at,
    };
    db.upsert_template_preset(&row).map_err(|e| format!("save preset: {}", e))?;
    Ok(out)
}

/// Phase 60 — Copy a builtin preset into a new user preset (assigns a new id + user:<uuid> kind,
/// name passed by the caller, version=1, builtin=false). Lets the user freely edit the forked copy.
pub fn fork_builtin_preset(
    kind: &str,
    name: &str,
) -> Result<TemplatePreset, String> {
    let name_trimmed = name.trim();
    if name_trimmed.is_empty() {
        return Err("name required".into());
    }
    if name_trimmed.len() > 64 {
        return Err("name too long (max 64)".into());
    }
    let src = builtin_presets().iter()
        .find(|p| p.kind == kind)
        .cloned()
        .ok_or_else(|| format!("unknown builtin kind: {}", kind))?;
    let new_id = gen_event_id();
    let out = TemplatePreset {
        id: new_id.clone(),
        name: name_trimmed.to_string(),
        description: src.description.clone(),
        kind: format!("user:{}", new_id),
        template: src.template.clone(),
        sample: src.sample.clone(),
        builtin: false,
        created_at: super::agent::now_secs(),
        version: 1,
        changelog: format!("Forked from builtin '{}' (v{})", src.name, src.version),
    };
    let row = crate::core::storage::TemplatePresetRow {
        id: out.id.clone(),
        name: out.name.clone(),
        description: if out.description.is_empty() { None } else { Some(out.description.clone()) },
        kind: out.kind.clone(),
        template: out.template.clone(),
        sample: if out.sample.is_empty() { None } else { Some(out.sample.clone()) },
        builtin: false,
        version: out.version,
        changelog: if out.changelog.is_empty() { None } else { Some(out.changelog.clone()) },
        created_at: out.created_at,
    };
    let store = super::shared_store().ok_or_else(|| "store unavailable".to_string())?;
    let mut s = store.lock().map_err(|_| "store poisoned".to_string())?;
    let StoreEnum::Db(db) = &mut *s else { return Err("sqlite store required".into()); };
    db.upsert_template_preset(&row).map_err(|e| format!("fork preset: {}", e))?;
    Ok(out)
}

/// Phase 59 — Delete only user presets (builtins untouched). Returns true when something was actually deleted.
pub fn delete_user_template_preset(id: &str) -> bool {
    let Some(store) = super::shared_store() else { return false };
    let Ok(mut s) = store.lock() else { return false };
    let StoreEnum::Db(db) = &mut *s else { return false };
    db.delete_template_preset(id)
}

/// Phase 59 — Serialize the preset list to YAML (serde_yaml also accepts JSON input).
pub fn export_presets_to_yaml(presets: &[TemplatePreset]) -> Result<String, String> {
    let doc = PresetYamlDoc { version: 1, presets: presets.to_vec() };
    serde_yaml::to_string(&doc).map_err(|e| format!("yaml serialize: {}", e))
}

/// Phase 59 — Import presets from YAML / JSON. Every preset is forced to builtin=false; a missing id gets an automatic UUID.
/// Phase 61 — First call `migrate_preset_yaml` to run the migration chain (legacy docs are auto-upgraded to CURRENT_DOC_VERSION).
/// Returns count of presets imported.
pub fn import_presets_from_yaml(yaml: &str) -> Result<usize, String> {
    let (doc, _applied) = migrate_preset_yaml(yaml)?;
    let store = super::shared_store().ok_or_else(|| "store unavailable".to_string())?;
    let mut s = store.lock().map_err(|_| "store poisoned".to_string())?;
    let StoreEnum::Db(db) = &mut *s else { return Err("sqlite store required".into()); };
    let mut count = 0;
    for mut p in doc.presets {
        p.builtin = false;
        if p.id.is_empty() {
            p.id = gen_event_id();
        }
        if p.name.trim().is_empty() {
            continue;
        }
        let row = crate::core::storage::TemplatePresetRow {
            id: p.id.clone(),
            name: p.name.clone(),
            description: if p.description.is_empty() { None } else { Some(p.description.clone()) },
            kind: if p.kind.is_empty() { format!("user:{}", p.id) } else { p.kind.clone() },
            template: p.template.clone(),
            sample: if p.sample.is_empty() { None } else { Some(p.sample.clone()) },
            builtin: false,
            version: p.version.max(1),
            changelog: if p.changelog.is_empty() { None } else { Some(p.changelog.clone()) },
            created_at: p.created_at,
        };
        let _ = db.upsert_template_preset(&row);
        count += 1;
    }
    Ok(count)
}

/// Phase 59 — Write a text file (used to persist an export). Phase 59 does not pull in the fs plugin; it uses std::fs directly.
pub fn write_text_file(path: &str, content: &str) -> Result<(), String> {
    std::fs::write(path, content).map_err(|e| format!("write file: {}", e))
}

pub fn read_text_file(path: &str) -> Result<String, String> {
    std::fs::read_to_string(path).map_err(|e| format!("read file: {}", e))
}

// ─── Phase 62 — Row → DTO converters (for bundle export) ──────────────────
// AlertingEndpointRow comes from the storage layer (integer fields are stored fairly raw),
// and is serialized as WebhookEndpoint when going out in a bundle (frontend / cross-process friendly).

fn endpoint_row_to_dto(row: &crate::core::storage::AlertingEndpointRow) -> WebhookEndpoint {
    // Phase 72 — deserialize the severity_overrides JSON. Missing / parse failure → empty Vec (equivalent to no override)
    let severity_overrides: Vec<(String, Severity)> = row
        .severity_overrides
        .as_deref()
        .and_then(|s| serde_json::from_str::<Vec<(String, String)>>(s).ok())
        .map(|pairs| {
            pairs
                .into_iter()
                .filter_map(|(src, sev)| Severity::parse(&sev).map(|parsed| (src, parsed)))
                .collect()
        })
        .unwrap_or_default();
    WebhookEndpoint {
        id: row.id.clone(),
        name: row.name.clone(),
        url: row.url.clone(),
        enabled: row.enabled,
        headers: row.headers.clone(),
        secret: row.secret.clone(),
        source_filter: row.source_filter.clone(),
        schema_version: row.schema_version,
        template: row.template.clone(),
        template_sample: row.template_sample.clone(),
        severity_overrides,
    }
}

fn silence_row_to_dto(row: &crate::core::storage::SilenceRuleRow) -> SilenceRule {
    SilenceRule {
        id: row.id.clone(),
        name: row.name.clone(),
        kind_pattern: row.kind_pattern.clone(),
        starts_at: row.starts_at,
        ends_at: row.ends_at,
        weekdays: row.weekdays,
        start_hour: row.start_hour,
        end_hour: row.end_hour,
    }
}

fn ack_row_to_dto(row: &crate::core::storage::AckRuleRow) -> AckRule {
    // The AckRule DTO is (kind_pattern, window_secs); the row is (id, kind_pattern, ack_until, created_at).
    // Take the remaining seconds as window_secs; if already expired fall back to 1 (avoid a 0 in the bundle, which validation would reject on import).
    let now = super::agent::now_secs();
    let remaining = if row.ack_until > now { row.ack_until - now } else { 1 };
    AckRule {
        kind_pattern: row.kind_pattern.clone(),
        window_secs: remaining,
    }
}

fn route_row_to_dto(row: &crate::core::storage::RouteRuleRow) -> RouteRule {
    RouteRule {
        id: row.id.clone(),
        name: row.name.clone(),
        priority: row.priority,
        enabled: row.enabled,
        kind_pattern: row.kind_pattern.clone(),
        payload_path: row.payload_path.clone(),
        payload_match: row.payload_match.clone(),
        target_endpoint_ids: row.target_endpoint_ids.clone(),
        recipients: row.recipients.clone(),
        tags: row.tags.clone(),
        seen_in_last: row.seen_in_last_json.as_deref().and_then(|s| {
            serde_json::from_str::<SeenInLastSpec>(s).ok()
        }),
    }
}

/// Phase 68 — `SeenInLastSpec` DTO → storage json string (None → None).
fn seen_in_last_to_json(spec: &Option<SeenInLastSpec>) -> Option<String> {
    spec.as_ref().and_then(|s| serde_json::to_string(s).ok())
}

/// Phase 62 — AckRule DTO → store. AckRule uses (kind_pattern, window_secs) semantics (consistent with `ack_kind`),
/// which do not align directly with the row's (id, kind_pattern, ack_until, created_at), so this thinly wraps `ack_kind`.
pub fn save_ack(rule: AckRule) -> Result<(), String> {
    if rule.window_secs == 0 || rule.window_secs > 7 * 86400 {
        return Err("ack window_secs must be 1..=604800".into());
    }
    ack_kind(rule.kind_pattern, rule.window_secs).map(|_| ())
}

/// Phase 62 — Full alerting config bundle document schema: five sections — endpoints + routes + presets + silences + acks.
/// The top carries `version` (bundle schema version) + `exportedAt` (unix seconds), for backup / cross-environment migration.
/// When a section is missing (not written in the yaml at all), serde default = empty vec, no error.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AlertingBundleDoc {
    #[serde(default = "default_bundle_doc_version")]
    pub version: u32,
    #[serde(default)]
    pub exported_at: u64,
    #[serde(default)]
    pub endpoints: Vec<WebhookEndpoint>,
    #[serde(default)]
    pub routes: Vec<RouteRule>,
    #[serde(default)]
    pub presets: Vec<TemplatePreset>,
    #[serde(default)]
    pub silences: Vec<SilenceRule>,
    #[serde(default)]
    pub acks: Vec<AckRule>,
    /// Phase 66 — reusable notification recipient definitions.
    /// Kind is whitelisted: `webhook` / `log:stderr` / `log:file` / `email:smtp`,
    /// config is a serde_json::Value (each kind has a different schema).
    #[serde(default)]
    pub recipients: Vec<RecipientDef>,
}

/// Phase 66 — recipient DTO shared by bundle + storage.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RecipientDef {
    #[serde(default)]
    pub id: String,
    pub name: String,
    pub kind: String,
    #[serde(default = "default_recipient_config")]
    pub config: serde_json::Value,
    #[serde(default = "default_true_for_recipient")]
    pub enabled: bool,
    #[serde(default)]
    pub created_at: u64,
}

fn default_recipient_config() -> serde_json::Value {
    serde_json::json!({})
}
fn default_true_for_recipient() -> bool {
    true
}

fn default_bundle_doc_version() -> u32 { 1 }

/// Phase 62 — Current bundle schema version. When Phase 63+ adds fields, bump it + add a migrator.
pub const CURRENT_BUNDLE_VERSION: u32 = 1;

/// Phase 62 — Import result stats, per-section counts + total.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
#[serde(rename_all = "camelCase")]
pub struct BundleImportSummary {
    pub endpoints: usize,
    pub routes: usize,
    pub presets: usize,
    pub silences: usize,
    pub acks: usize,
    /// Phase 66 — count for the top-level recipient definition section.
    /// Phase 66 only passes it through yaml (persistence is left to Phase 67).
    pub recipients: usize,
    pub total: usize,
}

/// Phase 62 — Serialize the whole alerting state (endpoints + routes + presets + silences + acks) to YAML / JSON.
/// presets include only user-defined ones; builtins are reloaded on the receiving side from backend constants.
/// Phase 64 — adds `passphrase: Option<&str>`:
/// - `None` → plaintext signed YAML (with a trailing `signature: <hex>`)
/// - `Some(pp)` → encrypted JSON envelope (salt+nonce+ciphertext, PBKDF2-derived key)
pub fn export_alerting_bundle(passphrase: Option<&str>) -> Result<String, String> {
    // endpoints: list_endpoints() returns AlertingEndpointRow, which must be converted to WebhookEndpoint before serializing
    // (otherwise AlertingEndpointRow lacks WebhookEndpoint's fields, and a future save_endpoint needs WebhookEndpoint arguments)
    let endpoint_rows = list_endpoints();
    let endpoints: Vec<WebhookEndpoint> = endpoint_rows.iter().map(endpoint_row_to_dto).collect();
    let route_rows = list_routes();
    let routes: Vec<RouteRule> = route_rows.iter().map(route_row_to_dto).collect();
    let silence_rows = list_silences();
    let silences: Vec<SilenceRule> = silence_rows.iter().map(silence_row_to_dto).collect();
    let ack_rows = list_acks();
    let acks: Vec<AckRule> = ack_rows.iter().map(ack_row_to_dto).collect();
    // builtin presets do not go into the bundle (the receiver loads them from backend constants); only user presets are included
    let presets: Vec<TemplatePreset> = list_template_presets()
        .into_iter()
        .filter(|p| !p.builtin)
        .collect();
    // Phase 67 — the recipients section is truly persisted (no longer passed through yaml)
    let recipients: Vec<RecipientDef> = list_recipients();
    let doc = AlertingBundleDoc {
        version: CURRENT_BUNDLE_VERSION,
        exported_at: super::agent::now_secs(),
        endpoints,
        routes,
        presets,
        silences,
        acks,
        recipients,
    };
    let yaml_body = serde_yaml::to_string(&doc).map_err(|e| format!("bundle serialize: {}", e))?;
    let signed = sign_bundle(&yaml_body)?;
    match passphrase {
        None => Ok(signed),
        Some(pp) => encrypt_bundle(&signed, pp),
    }
}

/// Phase 62 — Import a bundle document, upserting section by section. Preset builtin is forced = false (prevents a malicious bundle from overwriting).
/// Endpoints with the same name reuse the existing id; presets / routes / silences are overwritten by id. Returns per-section counts.
/// Phase 64 — `passphrase: Option<&str>`: `None` → expects plaintext signed YAML; `Some(pp)` → expects an encrypted envelope.
/// Auto-detection: try parsing as JSON + having `algorithm: aes-...-pbkdf2-sha256` → encrypted; otherwise treat as signed plaintext.
pub fn import_alerting_bundle(
    input: &str,
    passphrase: Option<&str>,
) -> Result<BundleImportSummary, String> {
    let signed_yaml = decode_bundle_input(input, passphrase)?;
    let (body, _sig) = split_signature(&signed_yaml)?;
    // verify the signature (constant time) to prevent tampering
    verify_bundle(&signed_yaml)?;
    let doc: AlertingBundleDoc = serde_yaml::from_str(body)
        .map_err(|e| format!("bundle yaml parse: {}", e))?;
    if doc.version > CURRENT_BUNDLE_VERSION {
        return Err(format!(
            "bundle version {} is newer than current {}; refusing to import future schema",
            doc.version, CURRENT_BUNDLE_VERSION
        ));
    }
    let mut summary = BundleImportSummary::default();
    // endpoints
    for ep in doc.endpoints {
        let _ = save_endpoint(ep).map_err(|e| format!("bundle endpoint: {}", e))?;
        summary.endpoints += 1;
    }
    // routes
    for rule in doc.routes {
        save_route(rule).map_err(|e| format!("bundle route: {}", e))?;
        summary.routes += 1;
    }
    // presets (builtin forced false)
    for mut p in doc.presets {
        p.builtin = false;
        if p.id.is_empty() {
            p.id = gen_event_id();
        }
        if p.kind.is_empty() {
            p.kind = format!("user:{}", p.id);
        }
        let _ = save_user_template_preset(&p)
            .map_err(|e| format!("bundle preset: {}", e))?;
        summary.presets += 1;
    }
    // silence
    for s in doc.silences {
        let _ = save_silence(s).map_err(|e| format!("bundle silence: {}", e))?;
        summary.silences += 1;
    }
    // acks: reuse the save_ack helper (already exists, written in Phase 50; check the name)
    for a in doc.acks {
        let _ = save_ack(a).map_err(|e| format!("bundle ack: {}", e))?;
        summary.acks += 1;
    }
    // Phase 67 — the recipients section is truly persisted (upserted one by one; kind must pass the whitelist)
    for rec in doc.recipients {
        validate_recipient_kind(&rec.kind)?;
        save_recipient(rec).map_err(|e| format!("bundle recipient: {e}"))?;
        summary.recipients += 1;
    }
    summary.total = summary.endpoints + summary.routes + summary.presets
        + summary.silences + summary.acks + summary.recipients;
    Ok(summary)
}

// ─── Phase 64: bundle signing + encryption ───────────────────────────────────

use hmac::{Hmac, Mac};
use sha2::Sha256;
type HmacSha256 = Hmac<Sha256>;

// ─── Phase 65: OS keychain integration for BUNDLE_SECRET ─────────────────────

/// Phase 65 — The bundle signing key is read from the OS keychain instead of a compile-time constant.
/// On first start it lazily generates 32 random bytes, stores them in the keychain (macOS Keychain / Windows
/// Credential Manager / Linux Secret Service); when the keychain is unavailable it degrades to
/// `dirs::config_dir()/opencapx/bundle-signing-v1.key`(chmod 0600)。
///
/// `sign_bundle` / `verify_bundle` no longer take a secret argument — internally they use `ensure_secret_loaded`
/// to get the current secret; `rotate_bundle_secret()` generates a new secret and writes it back to the keychain / file.

const KEYCHAIN_SERVICE: &str = "com.opencapx.desktop";
const KEYCHAIN_USER: &str = "bundle-signing-v1";
const FALLBACK_FILENAME: &str = "bundle-signing-v1.key";

static SECRET_BUF: Mutex<Vec<u8>> = Mutex::new(Vec::new());

/// Ensure the current process secret is loaded (empty buffer → try keychain → on failure degrade to file).
pub fn ensure_secret_loaded() -> Result<(), String> {
    {
        let guard = SECRET_BUF.lock().map_err(|_| "secret mutex poisoned".to_string())?;
        if !guard.is_empty() {
            return Ok(());
        }
    }
    // 1) prefer the keychain
    match load_from_keychain() {
        Ok(bytes) => {
            let mut guard = SECRET_BUF.lock().map_err(|_| "secret mutex poisoned".to_string())?;
            *guard = bytes;
            return Ok(());
        }
        Err(e) => {
            eprintln!("[opencapx] keychain unavailable ({e}); falling back to file secret");
        }
    }
    // 2) degrade to file
    let bytes = load_or_create_file_secret()?;
    let mut guard = SECRET_BUF.lock().map_err(|_| "secret mutex poisoned".to_string())?;
    *guard = bytes;
    Ok(())
}

/// Used by sign_bundle — returns an owned Vec<u8> (avoids calling Hmac while holding the lock).
pub fn current_secret_bytes() -> Result<Vec<u8>, String> {
    ensure_secret_loaded()?;
    let guard = SECRET_BUF.lock().map_err(|_| "secret mutex poisoned".to_string())?;
    Ok(guard.clone())
}

/// Phase 65: rotate the secret (generate a new 32 bytes, write keychain + degrade to file on failure, update the in-memory buffer).
/// A bundle exported under the old secret fails verification under the new secret.
pub fn rotate_bundle_secret() -> Result<(), String> {
    let mut bytes = vec![0u8; 32];
    getrandom::getrandom(&mut bytes).map_err(|e| format!("getrandom: {e}"))?;
    if let Err(e) = write_to_keychain(&bytes) {
        eprintln!("[opencapx] keychain rotate failed ({e}); falling back to file");
        write_fallback_secret(&bytes)?;
    }
    let mut guard = SECRET_BUF.lock().map_err(|_| "secret mutex poisoned".to_string())?;
    *guard = bytes;
    Ok(())
}

fn load_from_keychain() -> Result<Vec<u8>, String> {
    // cargo test skips the keychain: the test binary's hash changes on every rebuild, and the Keychain ACL
    // does not recognize it → get_password pops an infinite GUI authorization prompt (while still holding TEST_STORE_LOCK,
    // hanging the entire alerting test suite). Tests degrade to the file secret; sign/verify semantics are unchanged.
    if cfg!(test) {
        return Err("keychain disabled under cargo test".into());
    }
    let entry = keyring::Entry::new(KEYCHAIN_SERVICE, KEYCHAIN_USER)
        .map_err(|e| format!("keychain entry init: {e}"))?;
    let secret_b64 = entry
        .get_password()
        .map_err(|e| format!("keychain get_password: {e}"))?;
    let bytes = base64::Engine::decode(&base64::engine::general_purpose::STANDARD, &secret_b64)
        .map_err(|e| format!("base64 decode secret: {e}"))?;
    if bytes.len() != 32 {
        return Err(format!("keychain secret length {} != 32", bytes.len()));
    }
    Ok(bytes)
}

fn write_to_keychain(bytes: &[u8]) -> Result<(), String> {
    // same as load_from_keychain: the test process does not touch the keychain (set_password would also trigger an authorization prompt).
    if cfg!(test) {
        return Err("keychain disabled under cargo test".into());
    }
    let entry = keyring::Entry::new(KEYCHAIN_SERVICE, KEYCHAIN_USER)
        .map_err(|e| format!("keychain entry init: {e}"))?;
    let secret_b64 = base64::Engine::encode(&base64::engine::general_purpose::STANDARD, bytes);
    entry
        .set_password(&secret_b64)
        .map_err(|e| format!("keychain set_password: {e}"))
}

fn fallback_secret_path() -> Result<std::path::PathBuf, String> {
    let base = dirs::config_dir().ok_or_else(|| "no config_dir".to_string())?;
    Ok(base.join("opencapx").join(FALLBACK_FILENAME))
}

fn load_or_create_file_secret() -> Result<Vec<u8>, String> {
    use std::io::Read;
    let path = fallback_secret_path()?;
    if path.exists() {
        let mut f = std::fs::File::open(&path).map_err(|e| format!("open fallback: {e}"))?;
        let mut buf = Vec::new();
        f.read_to_end(&mut buf).map_err(|e| format!("read fallback: {e}"))?;
        if buf.len() != 32 {
            return Err(format!("fallback secret length {} != 32", buf.len()));
        }
        return Ok(buf);
    }
    let mut bytes = vec![0u8; 32];
    getrandom::getrandom(&mut bytes).map_err(|e| format!("getrandom: {e}"))?;
    write_fallback_secret(&bytes)?;
    Ok(bytes)
}

fn write_fallback_secret(bytes: &[u8]) -> Result<(), String> {
    use std::io::Write;
    let path = fallback_secret_path()?;
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent).map_err(|e| format!("mkdir fallback: {e}"))?;
    }
    let mut f = std::fs::File::create(&path).map_err(|e| format!("create fallback: {e}"))?;
    f.write_all(bytes).map_err(|e| format!("write fallback: {e}"))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o600))
            .map_err(|e| format!("chmod 0600 fallback: {e}"))?;
    }
    Ok(())
}

/// Phase 65 test-only — clear the in-memory buffer, forcing the next access to go through keychain/file again.
/// (rotate already updates the buffer itself; this function is a reset fixture for tests.)
#[cfg(test)]
pub fn reset_secret_buffer_for_test() {
    if let Ok(mut g) = SECRET_BUF.lock() {
        g.clear();
    }
}

/// Sign the whole yaml string and append a `signature: <hex>` line at the end.
/// `sig_hex = hex(hmac_sha256(yaml_body, current_secret))`。
/// Phase 65: the secret goes through a lazy accessor; sign_bundle no longer takes a `_secret` argument.
pub fn sign_bundle(yaml_body: &str) -> Result<String, String> {
    let secret = current_secret_bytes()?;
    let mut mac = HmacSha256::new_from_slice(&secret)
        .map_err(|e| format!("hmac init: {}", e))?;
    mac.update(yaml_body.as_bytes());
    let sig = mac.finalize().into_bytes();
    let sig_hex = sig.iter().map(|b| format!("{:02x}", b)).collect::<String>();
    let mut out = yaml_body.trim_end().to_string();
    out.push('\n');
    out.push_str(&format!("signature: \"{}\"\n", sig_hex));
    Ok(out)
}

/// Verify: split the body + sig out of a yaml string carrying `signature:`, then compare in constant time.
pub fn verify_bundle(signed_yaml: &str) -> Result<(), String> {
    let (body, sig_hex) = split_signature(signed_yaml)?;
    let secret = current_secret_bytes()?;
    let mut mac = HmacSha256::new_from_slice(&secret)
        .map_err(|e| format!("hmac init: {}", e))?;
    mac.update(body.as_bytes());
    let expected = mac.finalize().into_bytes();
    let provided = decode_hex(&sig_hex)?;
    if provided.len() != expected.len() {
        return Err("bundle signature length mismatch".into());
    }
    // constant-time comparison (hand-rolled, to avoid verify_slice's requirement that it consume the mac)
    let mut diff: u8 = 0;
    for (a, b) in expected.iter().zip(provided.iter()) {
        diff |= a ^ b;
    }
    if diff != 0 {
        return Err("bundle signature mismatch (content tampered)".into());
    }
    Ok(())
}

/// Decode a hex string of the form "xx xx xx" back to bytes (supports plain hex and space-separated formats).
fn decode_hex(s: &str) -> Result<Vec<u8>, String> {
    let s = s.trim();
    if s.len() % 2 != 0 {
        return Err(format!("hex string odd length: {}", s.len()));
    }
    let mut out = Vec::with_capacity(s.len() / 2);
    for i in (0..s.len()).step_by(2) {
        let byte = u8::from_str_radix(&s[i..i + 2], 16)
            .map_err(|e| format!("hex parse at {}: {}", i, e))?;
        out.push(byte);
    }
    Ok(out)
}

/// Split a yaml string carrying a `signature:` line into (body_before_sig, sig_hex).
/// Allows a preceding `\n` before the signature line, with or without spaces/quotes after it.
fn split_signature(signed_yaml: &str) -> Result<(&str, String), String> {
    let bytes = signed_yaml.as_bytes();
    let needle = b"signature:";
    // find the last `signature:` (guards against a same-named key inside the yaml body)
    let mut last = None;
    let mut i = 0;
    while i + needle.len() <= bytes.len() {
        if &bytes[i..i + needle.len()] == needle {
            // ensure it is at line start (preceded by \n or the start)
            if i == 0 || bytes[i - 1] == b'\n' {
                last = Some(i);
            }
        }
        i += 1;
    }
    let idx = last.ok_or_else(|| "bundle missing signature: field".to_string())?;
    let body = &signed_yaml[..idx];
    // skip all spaces + optional quotes after `signature:`
    let rest = &signed_yaml[idx + needle.len()..];
    let rest = rest.trim_start();
    let rest = if let Some(stripped) = rest.strip_prefix('"') {
        stripped
    } else {
        rest
    };
    let end = rest.find(|c: char| c == '"' || c == '\n' || c == ' ').unwrap_or(rest.len());
    let sig = rest[..end].to_string();
    Ok((body, sig))
}

/// Encrypted JSON envelope top-level schema.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct EncryptedEnvelope {
    version: u32,
    algorithm: String,
    kdf: String,
    iterations: u32,
    salt: String,         // base64
    nonce: String,         // base64
    ciphertext: String,    // base64
}

/// Phase 64 — Encrypt the whole signed YAML with a passphrase (using AES-256-GCM + a PBKDF2-SHA256-derived key).
/// Returns envelope JSON (safe to drop into git / email / any text channel).
pub fn encrypt_bundle(signed_yaml: &str, passphrase: &str) -> Result<String, String> {
    if passphrase.is_empty() {
        return Err("passphrase must not be empty".into());
    }
    use aes_gcm::aead::{Aead, KeyInit};
    use aes_gcm::{Aes256Gcm, Nonce};
    use base64::{engine::general_purpose::STANDARD as B64, Engine as _};
    use getrandom::getrandom;
    use pbkdf2::pbkdf2_hmac;

    let mut salt = [0u8; 16];
    getrandom(&mut salt).map_err(|e| format!("getrandom salt: {}", e))?;
    let mut nonce_bytes = [0u8; 12];
    getrandom(&mut nonce_bytes).map_err(|e| format!("getrandom nonce: {}", e))?;

    let iterations = 100_000u32;
    let mut key = [0u8; 32];
    pbkdf2_hmac::<Sha256>(passphrase.as_bytes(), &salt, iterations, &mut key);
    let cipher = Aes256Gcm::new_from_slice(&key)
        .map_err(|e| format!("aes init: {}", e))?;
    let nonce = Nonce::from_slice(&nonce_bytes);
    let ciphertext = cipher
        .encrypt(nonce, signed_yaml.as_bytes())
        .map_err(|e| format!("aes encrypt: {}", e))?;

    let envelope = EncryptedEnvelope {
        version: 1,
        algorithm: "aes-256-gcm-pbkdf2-sha256".into(),
        kdf: "pbkdf2-sha256".into(),
        iterations,
        salt: B64.encode(salt),
        nonce: B64.encode(nonce_bytes),
        ciphertext: B64.encode(ciphertext),
    };
    serde_json::to_string_pretty(&envelope).map_err(|e| format!("envelope serialize: {}", e))
}

/// Phase 64 — Decrypt an envelope back to signed YAML. Requires the correct passphrase + intact nonce + salt.
pub fn decrypt_bundle(envelope_json: &str, passphrase: &str) -> Result<String, String> {
    use aes_gcm::aead::{Aead, KeyInit};
    use aes_gcm::{Aes256Gcm, Nonce};
    use base64::{engine::general_purpose::STANDARD as B64, Engine as _};
    use pbkdf2::pbkdf2_hmac;

    let env: EncryptedEnvelope = serde_json::from_str(envelope_json)
        .map_err(|e| format!("envelope parse: {}", e))?;
    if env.algorithm != "aes-256-gcm-pbkdf2-sha256" {
        return Err(format!("unsupported algorithm: {}", env.algorithm));
    }
    let salt = B64.decode(&env.salt).map_err(|e| format!("salt decode: {}", e))?;
    let nonce_bytes = B64.decode(&env.nonce).map_err(|e| format!("nonce decode: {}", e))?;
    let ciphertext = B64
        .decode(&env.ciphertext)
        .map_err(|e| format!("ciphertext decode: {}", e))?;
    if nonce_bytes.len() != 12 {
        return Err("nonce must be 12 bytes".into());
    }
    let mut key = [0u8; 32];
    pbkdf2_hmac::<Sha256>(passphrase.as_bytes(), &salt, env.iterations, &mut key);
    let cipher = Aes256Gcm::new_from_slice(&key)
        .map_err(|e| format!("aes init: {}", e))?;
    let nonce = Nonce::from_slice(&nonce_bytes);
    let plaintext = cipher
        .decrypt(nonce, ciphertext.as_ref())
        .map_err(|_| "decryption failed (wrong passphrase or tampered ciphertext)".to_string())?;
    String::from_utf8(plaintext).map_err(|e| format!("decoded not utf8: {}", e))
}

/// Phase 64 — Auto-detect the input format, decrypt (if encrypted) + return the final signed YAML.
/// plaintext passes straight through; encrypted requires a passphrase.
fn decode_bundle_input(input: &str, passphrase: Option<&str>) -> Result<String, String> {
    let trimmed = input.trim_start();
    if trimmed.starts_with('{') {
        // may be an encrypted envelope (JSON); if the algorithm field matches → decrypt
        if let Ok(env) = serde_json::from_str::<EncryptedEnvelope>(trimmed) {
            if env.algorithm.starts_with("aes-256-gcm") {
                let pp = passphrase.ok_or_else(|| {
                    "this bundle is passphrase-encrypted; please provide passphrase".to_string()
                })?;
                return decrypt_bundle(trimmed, pp);
            }
        }
        // not an envelope → take the plain path
    }
    Ok(input.to_string())
}

/// Look up path on the envelope and return the JSON value (supports `payload.x.y`).
fn lookup_path_value<'a>(env: &'a AlertEnvelope, path: &str) -> serde_json::Value {
    let path = path.trim();
    if let Some(rest) = path.strip_prefix("payload.") {
        return lookup_json_path(&env.payload, rest).cloned().unwrap_or(serde_json::Value::Null);
    }
    match path {
        "source" => serde_json::Value::String(env.source.clone()),
        "severity" => serde_json::Value::String(env.severity.as_str().to_string()),
        "timestamp" => serde_json::Value::Number(env.timestamp.into()),
        "event_id" => serde_json::Value::String(env.event_id.clone()),
        "schema_version" => serde_json::Value::Number(env.schema_version.into()),
        "tags" => serde_json::Value::Array(
            env.tags.iter().map(|s| serde_json::Value::String(s.clone())).collect(),
        ),
        _ => serde_json::Value::Null,
    }
}

/// Stringified version used when rendering (numbers / bool go through serde_json serialization).
fn lookup_path_string(env: &AlertEnvelope, path: &str) -> String {
    value_to_string(&lookup_path_value(env, path))
}

/// Look up a dot-path on any `serde_json::Value`.
fn lookup_json_path<'a>(v: &'a serde_json::Value, path: &str) -> Option<&'a serde_json::Value> {
    let mut cur = v;
    for seg in path.split('.') {
        match cur {
            serde_json::Value::Object(m) => {
                cur = m.get(seg)?;
            }
            _ => return None,
        }
    }
    Some(cur)
}

/// Used by `{{#each path}}`: returns an array; non-arrays yield an empty array.
fn lookup_path_array(env: &AlertEnvelope, path: &str) -> Option<Vec<serde_json::Value>> {
    match lookup_path_value(env, path) {
        serde_json::Value::Array(a) => Some(a),
        _ => None,
    }
}

fn value_to_string(v: &serde_json::Value) -> String {
    match v {
        serde_json::Value::String(s) => s.clone(),
        serde_json::Value::Null => String::new(),
        other => other.to_string(),
    }
}

// ─── Phase 53: severity hints (manifest + user) ───────────────────────────────

/// Phase 53 — Public DTO for one severity hint (used by the settings UI + tauri commands).
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SeverityHintDto {
    pub source: String,
    pub severity: String,
    pub origin: String,
    #[serde(rename = "pluginId", skip_serializing_if = "Option::is_none")]
    pub plugin_id: Option<String>,
    #[serde(rename = "updatedAt")]
    pub updated_at: i64,
    /// Phase 69 — the severity actually in effect (resolved through the chain; the UI can display it directly without recomputing).
    #[serde(rename = "effectiveSeverity")]
    pub effective_severity: String,
}

/// Phase 69 — 4-stage enum for the severity chain.
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SeverityPolicy {
    /// Phase 53 — hint declared by the plugin manifest.
    Manifest,
    /// Phase 53 — hardcoded default (the `severity_for_source` static table).
    PluginDefault,
    /// Phase 53 — hint set manually by the user.
    UserOverride,
    /// Phase 69 — the user explicitly disabled alerts for a source (currently only a placeholder, no set implemented).
    Disabled,
}

/// Phase 69 — each link on the chain, with `hit` marking whether it took effect.
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SeverityLink {
    pub policy: SeverityPolicy,
    pub severity: Option<Severity>,
    pub source: String,
    #[serde(rename = "pluginId", skip_serializing_if = "Option::is_none")]
    pub plugin_id: Option<String>,
    pub hit: bool,
}

/// Phase 69 — impact report for a cascade delete.
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct CascadeReport {
    pub hint_deleted: bool,
    pub affected_routes: Vec<String>,
    pub affected_correlations: Vec<String>,
    pub affected_aggregations: Vec<String>,
}

/// Phase 53 — public mirror of the `alerting.severityHints` sub-structure (loaded by the plugin module).
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize, Default)]
#[serde(rename_all = "camelCase")]
pub struct AlertingManifest {
    #[serde(default)]
    pub severity_hints: std::collections::HashMap<String, String>,
}

/// Phase 69 — Produce the 4-layer chain for a source (always returns 4 links, ordered Manifest → PluginDefault → UserOverride → Disabled).
/// Each layer's `hit` marks whether it actually took effect for that source.
pub fn severity_inheritance_chain(source: &str) -> Vec<SeverityLink> {
    let user_hit = severity_hint_lookup(source, "user").is_some();
    let manifest_row = crate::core::storage::with_store(|s| {
        s.get_alerting_severity_hint(source, "manifest")
    })
    .flatten();
    let manifest_hit = manifest_row.is_some() && !user_hit;
    let default_hit = manifest_row.is_none() && !user_hit;
    let mut chain = Vec::with_capacity(4);
    chain.push(SeverityLink {
        policy: SeverityPolicy::Manifest,
        severity: severity_hint_lookup(source, "manifest"),
        source: source.to_string(),
        plugin_id: manifest_row.and_then(|r| r.plugin_id),
        hit: manifest_hit,
    });
    chain.push(SeverityLink {
        policy: SeverityPolicy::PluginDefault,
        severity: Some(severity_for_source(source)),
        source: source.to_string(),
        plugin_id: None,
        hit: default_hit,
    });
    chain.push(SeverityLink {
        policy: SeverityPolicy::UserOverride,
        severity: severity_hint_lookup(source, "user"),
        source: source.to_string(),
        plugin_id: None,
        hit: user_hit,
    });
    chain.push(SeverityLink {
        policy: SeverityPolicy::Disabled,
        severity: None,
        source: source.to_string(),
        plugin_id: None,
        hit: false, // Phase 69 does not implement set yet
    });
    chain
}

/// Phase 69 — Produce the source's effective severity + which layer was hit.
pub fn effective_severity_with_reason(source: &str) -> (Severity, SeverityLink) {
    let chain = severity_inheritance_chain(source);
    let hit_link = chain
        .into_iter()
        .find(|l| l.hit)
        .unwrap_or(SeverityLink {
            policy: SeverityPolicy::PluginDefault,
            severity: Some(Severity::Info),
            source: source.to_string(),
            plugin_id: None,
            hit: false,
        });
    (hit_link.severity.unwrap_or(Severity::Info), hit_link)
}

/// Phase 69 — Delete the user-origin hint + list affected routes / correlations / aggregations.
/// Manifest hints are not deleted (managed by the plugin lifecycle).
pub fn cascade_delete_severity_hint(source: &str) -> CascadeReport {
    let user_deleted = delete_user_severity_hint(source);
    let routes = list_routes();
    let affected_routes: Vec<String> = routes
        .into_iter()
        .filter(|r| {
            r.kind_pattern == source
                || r.seen_in_last_json
                    .as_deref()
                    .and_then(|j| serde_json::from_str::<SeenInLastSpec>(j).ok())
                    .map(|s| s.pattern == source)
                    .unwrap_or(false)
        })
        .map(|r| r.name)
        .collect();
    let corrs = list_correlations();
    let affected_correlations: Vec<String> = corrs
        .into_iter()
        .filter(|c| c.kind_pattern_a == source || c.kind_pattern_b == source)
        .map(|c| c.name)
        .collect();
    let aggs = list_aggregations();
    let affected_aggregations: Vec<String> = aggs
        .into_iter()
        .filter(|a| a.kind_pattern == source)
        .map(|a| a.name)
        .collect();
    CascadeReport {
        hint_deleted: user_deleted,
        affected_routes,
        affected_correlations,
        affected_aggregations,
    }
}

/// Precedence chain: user hint → manifest hint → hardcode → Info. With no store it falls straight back to hardcode.
pub fn severity_resolved(source: &str) -> Severity {
    effective_severity_with_reason(source).0
}

// Phase 70 — Severity cross-chain propagation helpers
//
// The four main chains (route dispatch / correlation suppress / aggregation action /
// escalation target) all take severity through `severity_resolved`. The function names are split only for
// trace and grep friendliness: semantically they are 4 distinct chain points, but the current implementation is equivalent to
// `severity_resolved(source)`. Phase 70 keeps this equivalence; the main paths will be wired in step by step
// after trace is exposed (avoiding a one-shot change that widens the regression surface).

/// Phase 70 — Route chain takes severity (equivalent to `severity_resolved`)
pub fn route_dispatch_severity(source: &str) -> Severity {
    severity_resolved(source)
}

/// Phase 70 — Correlation chain takes severity (equivalent to `severity_resolved`)
pub fn correlation_decision_severity(source: &str) -> Severity {
    severity_resolved(source)
}

/// Phase 70 — Aggregation chain takes severity (equivalent to `severity_resolved`)
pub fn aggregation_action_severity(source: &str) -> Severity {
    severity_resolved(source)
}

/// Phase 70 — Escalation chain takes severity (equivalent to `severity_resolved`)
pub fn escalation_target_severity(source: &str) -> Severity {
    severity_resolved(source)
}

/// Phase 70 — Propagation consistency trace DTO.
///
/// When the four main chains take severity for one source, which final value each uses + which link of the chain
/// it comes from. `severity_inheritance_chain` (Phase 69) shows the chain as a whole;
/// `propagation_trace` (Phase 70) shows how the chain's hit is applied across the four downstream chains.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PropagationTrace {
    pub source: String,
    pub route_severity: Severity,
    pub route_origin: SeverityPolicy,
    pub correlation_severity: Severity,
    pub correlation_origin: SeverityPolicy,
    pub aggregation_severity: Severity,
    pub aggregation_origin: SeverityPolicy,
    pub escalation_severity: Severity,
    pub escalation_origin: SeverityPolicy,
}

/// Phase 70 — Take a source's effective severity + origin across the 4 main chains.
pub fn propagation_trace(source: &str) -> PropagationTrace {
    let (sev, link) = effective_severity_with_reason(source);
    PropagationTrace {
        source: source.to_string(),
        route_severity: sev,
        route_origin: link.policy,
        correlation_severity: sev,
        correlation_origin: link.policy,
        aggregation_severity: sev,
        aggregation_origin: link.policy,
        escalation_severity: sev,
        escalation_origin: link.policy,
    }
}

// Phase 74 — endpoint override dry-run preview (does not trigger dispatch; pure function + list_alerting_endpoints)

/// Phase 74 — one override hit record
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct EndpointSeverityOverrideHit {
    pub pattern: String,
    pub severity: Severity,
    pub index: usize,
}

/// Phase 74 — preview result for a single endpoint (propagation + override hit + final)
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct EndpointPreviewRow {
    pub endpoint_id: String,
    pub endpoint_name: String,
    pub override_hit: Option<EndpointSeverityOverrideHit>,
    pub propagation_severity: Severity,
    pub final_envelope_severity: Severity,
}

/// Phase 74 — overall result of one preview (the source + one row per endpoint)
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct EndpointSeverityPreview {
    pub source: String,
    pub endpoints: Vec<EndpointPreviewRow>,
}

/// Phase 74 — pure function: compute one preview row for a source + endpoint DTO
pub fn preview_endpoint_severity(source: &str, ep: &WebhookEndpoint) -> EndpointPreviewRow {
    let propagation = severity_resolved(source);
    let hit = ep
        .severity_overrides
        .iter()
        .enumerate()
        .find(|(_, (pattern, _))| kind_matches(pattern, source))
        .map(|(i, (pattern, sev))| EndpointSeverityOverrideHit {
            pattern: pattern.clone(),
            severity: *sev,
            index: i,
        });
    let final_sev = hit.as_ref().map(|h| h.severity).unwrap_or(propagation);
    EndpointPreviewRow {
        endpoint_id: ep.id.clone(),
        endpoint_name: ep.name.clone(),
        override_hit: hit,
        propagation_severity: propagation,
        final_envelope_severity: final_sev,
    }
}

/// Phase 74 — entry point: preview from the fanout perspective
/// endpoint_id = None → all enabled endpoints; Some(id) → only that endpoint (enabled is not filtered, letting the user dry-run a disabled one)
pub fn preview_alerting_endpoint_severity(
    source: &str,
    endpoint_id: Option<&str>,
) -> Result<EndpointSeverityPreview, String> {
    if source.trim().is_empty() {
        return Err("source is required".into());
    }
    // Phase 74 — preview must be computed after releasing the store lock, because severity_resolved calls
    // severity_inheritance_chain → with_store locks the same Mutex again (std::sync::Mutex is not reentrant).
    let targets: Vec<WebhookEndpoint> = {
        let store = super::shared_store().ok_or_else(|| "store not initialized".to_string())?;
        let s = store.lock().map_err(|_| "store poisoned".to_string())?;
        let StoreEnum::Db(db) = &*s else { return Err("sqlite store required".into()) };
        let rows = db.list_alerting_endpoints();
        match endpoint_id {
            Some(id) if !id.is_empty() => rows
                .into_iter()
                .find(|r| r.id == id)
                .map(|r| vec![endpoint_row_to_dto(&r)])
                .unwrap_or_default(),
            _ => rows.iter().filter(|r| r.enabled).map(endpoint_row_to_dto).collect(),
        }
        // the lock drops at the end of the block
    };
    let endpoints = targets
        .iter()
        .map(|ep| preview_endpoint_severity(source, ep))
        .collect();
    Ok(EndpointSeverityPreview {
        source: source.to_string(),
        endpoints,
    })
}

// ─── Phase 75: Alerting full-chain dry-run simulator ─────────────────────────

